import { useMediaQuery, useTheme } from "@mui/material";
import { Fragment } from "react";
import { Link, useLocation } from "react-router-dom";
import { StyledFlexBox, StyledImage } from "../../styles/Shared.styles";

const LEFT_BAR_ITEMS = [
  {
    text: "\u6703\u54e1\u7ba1\u7406",
    link: "/member",
    icon: "/images/icon-member.svg",
    activeIcon: "/images/icon-member-active.svg",
  },
  {
    text: "\u6a19\u7c64\u7ba1\u7406",
    link: "/label",
    icon: "/images/icon-setup.svg",
    activeIcon: "/images/icon-setup-active.svg",
  },
  {
    text: "\u8a02\u55ae\u7ba1\u7406",
    link: "/order",
    icon: "/images/icon-report.svg",
    activeIcon: "/images/icon-report-active.svg",
  },
  {
    text: "\u4ed8\u6b3e\u7d00\u9304",
    link: "/payment-record",
    icon: "/images/icon-report.svg",
    activeIcon: "/images/icon-report-active.svg",
  },
  {
    text: "\u5e33\u52d9\u7ba1\u7406",
    link: "/business",
    icon: "/images/icon-report.svg",
    activeIcon: "/images/icon-report-active.svg",
  },
  {
    text: "\u8a2d\u5b9a\u7ba1\u7406",
    link: "/setting",
    icon: "/images/icon-setup.svg",
    activeIcon: "/images/icon-setup-active.svg",
  },
];

const LeftBar = () => {
  const { pathname } = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));

  return (
    <StyledFlexBox
      bg="#fff"
      position="fixed"
      top={52}
      width={isMobile ? 60 : 180}
      height="100%"
      flexDirection="column"
      sx={{
        pt: isMobile ? 1 : 2,
      }}
    >
      {LEFT_BAR_ITEMS.map((item) => {
        const isActive = pathname.startsWith(item.link);

        return (
          <Fragment key={item.text}>
            <Link to={item.link} style={{ textDecoration: "none" }}>
              <StyledFlexBox
                alignItems="center"
                height={50}
                color={isActive ? "#fff" : "#a7a7a7"}
                bg={isActive ? "#8c9eff" : "inherit"}
                pl={isMobile ? 0 : 2}
                sx={{
                  justifyContent: isMobile ? "center" : "flex-start",
                  fontSize: 14,
                  "&:hover": {
                    backgroundColor: isActive ? "#8c9eff" : "#f2f2f2",
                  },
                }}
              >
                <StyledImage
                  src={isActive ? item.activeIcon : item.icon}
                  mr={isMobile ? "0px" : "12px"}
                />
                {!isMobile && item.text}
              </StyledFlexBox>
            </Link>
          </Fragment>
        );
      })}
    </StyledFlexBox>
  );
};

export default LeftBar;
