import {
  Alert,
  Box,
  Button,
  Checkbox,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from "@mui/material";
import { useEffect, useState } from "react";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import * as XLSX from "xlsx";
import {
  batchUpdatePurchaseIsCharge,
  fetchBusinessAccountList,
  fetchPhotographerReport,
} from "../../../../src/api/Business";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

const FEE_RATE = 0.028;

function formatDate(d) {
  if (!d) return "";
  const dt = new Date(d);
  return `${dt.getFullYear()}/${dt.getMonth() + 1}/${dt.getDate()}`;
}

const FinanceManagement = () => {
  const [list, setList] = useState([]);
  const [page, setPage] = useState(0);
  const [limit, setLimit] = useState(10);
  const [totalCount, setTotalCount] = useState(0);
  const [totalMoney, setTotalMoney] = useState(0);
  const [totalPhotographerMoney, setTotalPhotographerMoney] = useState(0);
  const [purchaseType, setPurchaseType] = useState("");
  const [dateRange, setDateRange] = useState([null, null]);
  const [startDate, endDate] = dateRange;

  const [sortField, setSortField] = useState("id");
  const [sortOrder, setSortOrder] = useState("desc");

  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedRow, setSelectedRow] = useState(null);

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("info");

  const [selectedIds, setSelectedIds] = useState([]);
  const [confirmBatchOpen, setConfirmBatchOpen] = useState(false);
  const [batchDateRange, setBatchDateRange] = useState([null, null]);
  const [batchStartDate, batchEndDate] = batchDateRange;

  const showSnackbar = (msg, severity = "info") => {
    setSnackbarMsg(msg);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => setSnackbarOpen(false);
  function formatLocalDate(date) {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }
  const fetchData = async () => {
    try {
      const res = await fetchBusinessAccountList({
        page: page + 1,
        limit,
        purchase_type: purchaseType,
        begin_date: startDate ? formatLocalDate(startDate) : undefined,
        end_date: endDate
          ? formatLocalDate(new Date(endDate.getTime() + 24 * 60 * 60 * 1000))
          : undefined,

        sort: sortField,
        order: sortOrder,
      });
      if (res?.success) {
        setList(res.data.business_responses.records);
        setTotalCount(res.data.business_responses.page.total_count || 0);
        setTotalPhotographerMoney(res.data.total_photographer_commission);
        setTotalMoney(res.data.total_amount);
      } else {
        showSnackbar("取得帳務資料失敗", "error");
      }
    } catch (err) {
      console.error("fetch error", err);
      showSnackbar("伺服器錯誤", "error");
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, limit, sortField, sortOrder]);

  const handleSearch = () => {
    setPage(0);
    fetchData();
  };

  const handleClickDetail = (row) => {
    setSelectedRow(row);
    setDialogOpen(true);
  };
  const handleCloseDialog = () => {
    setDialogOpen(false);
    setSelectedRow(null);
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
  };

  const handleToggleSelect = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((v) => v !== id) : [...prev, id]
    );
  };

  const handleSelectAll = (checked) => {
    if (checked) {
      const unchargedIds = list.filter((r) => !r.is_charge).map((r) => r.id);
      setSelectedIds(unchargedIds);
    } else {
      setSelectedIds([]);
    }
  };

  const handleOpenConfirmBatch = () => {
    setBatchDateRange([startDate ?? null, endDate ?? null]);
    setConfirmBatchOpen(true);
  };

  const handleCloseConfirmBatch = () => {
    setConfirmBatchOpen(false);
    setBatchDateRange([null, null]);
  };

  const handleSubmitBatch = async () => {
    if (!batchStartDate || !batchEndDate) {
      showSnackbar("請選擇清帳的開始與結束時間", "warning");
      return;
    }
    try {
      const res = await batchUpdatePurchaseIsCharge({
        ids: selectedIds,
        start_date: batchStartDate
          ? batchStartDate.toISOString().split("T")[0]
          : undefined,
        end_date: batchEndDate
          ? new Date(batchEndDate.getTime() + 24 * 60 * 60 * 1000)
              .toISOString()
              .split("T")[0]
          : undefined,
      });
      console.log(res)
      if (res?.success) {
        showSnackbar("批次清帳完成", "success");
        setSelectedIds([]);
        fetchData();
      } else {
        showSnackbar("批次清帳失敗", "error");
      }
    } catch (err) {
      console.error("批次錯誤", err);
      showSnackbar("批次清帳失敗", "error");
    } finally {
      setConfirmBatchOpen(false);
    }
  };

  const handleExportExcel = async () => {
    try {
      const res = await fetchPhotographerReport({
        begin_date: startDate ? formatLocalDate(startDate) : undefined,
        end_date: endDate
          ? formatLocalDate(new Date(endDate.getTime() + 24 * 60 * 60 * 1000))
          : undefined,
      });

      if (!res?.success) throw new Error("API 失敗");

      const orders = (Array.isArray(res?.data) && res.data) || [];
      const rows = [];
      let totalNp = 0; // 藍新沒扣手續費（總）
      let totalFee = 0; // 藍新手續費（總）
      let totalNet = 0; // 藍新扣手續費（總）
      let totalPlatformIncome = 0; // 收入（平台抽成）
      let totalPayPhotographer = 0; // 支付攝影師款
      let totalBCoin = 0; // B幣相關
      for (const order of orders) {
        const {
          order_id,
          user_id,
          p_id,
          pname,
          create_time,
          type,
          mains,
          subs,
          total_amount,
          platformAmount,
          pAmount,
          pbank_code,
          pbank_id,
          end_time,
        } = order;

        // 客戶下單
        rows.push({
          訂單編號: order_id,
          用戶ID: user_id,
          攝影師ID: p_id ?? "",
          攝影師姓名: pname ?? "",
          日期: formatDate(create_time),
          事件類型: "客戶下單",
        });
        totalPlatformIncome += platformAmount ?? 0;
        totalPayPhotographer += pAmount ?? 0;
        // mains
        for (const main of mains || []) {
          if (main.type === "np") {
            const pay = main.pay_amount;
            const payDate = formatDate(main.pay_time);
            const bankAmount = Math.round(pay * (1 - FEE_RATE));
            const fee = pay - bankAmount;
            totalNp += main.pay_amount;
            totalFee += fee;
            totalNet += main.pay_amount - fee;
            rows.push({
              訂單編號: order_id,
              用戶ID: user_id,
              攝影師ID: p_id ?? "",
              攝影師姓名: pname ?? "",
              日期: payDate,
              事件類型: "客戶付款(主訂單)",
              借方科目: "應收藍新金流",
              借方金額: pay,
              貸方科目: "預收款",
              貸方金額: pay,
            });
            rows.push({
              訂單編號: order_id,
              用戶ID: user_id,
              攝影師ID: p_id ?? "",
              攝影師姓名: pname ?? "",
              日期: "",
              事件類型: "藍新撥款(主訂單)",
              借方科目: "銀行存款",
              借方金額: bankAmount,
              貸方科目: "應收藍新金流",
              貸方金額: pay,
            });
            rows.push({
              訂單編號: order_id,
              用戶ID: user_id,
              攝影師ID: p_id ?? "",
              攝影師姓名: pname ?? "",
              日期: payDate,
              事件類型: "藍新手續費(主訂單)",
              借方科目: "手續費",
              借方金額: fee,
            });
          } else if (main.type === "bc") {
            totalBCoin += main.pay_amount;
            rows.push({
              訂單編號: order_id,
              用戶ID: user_id,
              攝影師ID: p_id ?? "",
              攝影師姓名: pname ?? "",
              日期: formatDate(main.pay_time),
              事件類型: "客戶付款(B幣)",
              借方科目: "B幣負債",
              借方金額: main.pay_amount,
              貸方科目: "預收款",
              貸方金額: main.pay_amount,
            });
          }
        }

        // subs
        for (const sub of subs || []) {
          const pay = sub.pay_amount;
          const payDate = formatDate(sub.pay_time);
          const bankAmount = Math.round(pay * (1 - FEE_RATE));
          const fee = pay - bankAmount;
          totalNp += sub.pay_amount;
          totalFee += fee;
          totalNet += sub.pay_amount - fee;
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: payDate,
            事件類型: "客戶付款(加時)",
            借方科目: "應收藍新金流",
            借方金額: pay,
            貸方科目: "預收款",
            貸方金額: pay,
          });
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: payDate,
            事件類型: "藍新撥款(加時)",
            借方科目: "銀行存款",
            借方金額: bankAmount,
            貸方科目: "應收藍新金流",
            貸方金額: pay,
          });
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: payDate,
            事件類型: "藍新手續費(加時)",
            借方科目: "手續費",
            借方金額: fee,
          });
        }

        // 結案 or 退款
        if (type !== "CANCEL") {
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: formatDate(create_time),
            事件類型: "結案認列收入",
            借方科目: "預收款",
            借方金額: total_amount,
            貸方科目: "收入(平台抽成)",
            貸方金額: platformAmount,
          });
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: formatDate(create_time),
            事件類型: "結案認列收入",
            貸方科目: "應付攝影師款",
            貸方金額: pAmount,
          });
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: formatDate(end_time),
            事件類型: "支付攝影師款",
            借方科目: "應付攝影師款",
            借方金額: pAmount,
            貸方科目: "銀行存款",
            貸方金額: pAmount,
            銀行代號: pbank_code ?? "",
            銀行帳號: pbank_id ?? "",
          });
        } else {
          rows.push({
            訂單編號: order_id,
            用戶ID: user_id,
            攝影師ID: p_id ?? "",
            攝影師姓名: pname ?? "",
            日期: formatDate(create_time),
            事件類型: "退款轉B幣",
            借方科目: "預收款",
            借方金額: total_amount,
            貸方科目: "B幣負債",
            貸方金額: total_amount,
          });
        }

        // 🔽 最後分類判斷
        let orderTypeDesc = "普通訂單";
        if (subs && subs.length > 0) {
          orderTypeDesc = "拍攝中有加時的訂單";
        }
        if (mains && mains.every((m) => m.type === "bc")) {
          orderTypeDesc = "使用B幣付款";
        }
        if (
          mains &&
          mains.some((m) => m.type === "bc") &&
          mains.some((m) => m.type === "np")
        ) {
          orderTypeDesc = "因B幣餘額不足，需B幣+藍新付款";
        }
        if (type === "CANCEL") {
          orderTypeDesc = "付款後因訂單取消，退B幣";
        }

        rows.push({
          訂單編號: order_id,
          用戶ID: user_id,
          攝影師ID: p_id ?? "",
          攝影師姓名: pname ?? "",
          日期: "",
          事件類型: `【分類】${orderTypeDesc}`,
          狀態: orderTypeDesc,
        });
      }

      // 產生 Excel
      const headers = [
        "訂單編號",
        "用戶ID",
        "攝影師ID",
        "攝影師姓名",
        "日期",
        "事件類型",
        "借方科目",
        "借方金額",
        "貸方科目",
        "貸方金額",
        "備註",
        "銀行代號",
        "銀行帳號",
        "狀態",
      ];
      const summaryRows = [
        ["藍新沒扣手續費（總）", totalNp],
        ["藍新手續費（總）", Math.round(totalFee)],
        ["藍新扣手續費（總）", Math.round(totalNet)],
        ["收入（平台抽成）（總）", totalPlatformIncome],
        ["支付攝影師款（總）", totalPayPhotographer],
        ["B幣預收（總）", totalBCoin],
        ["客戶付款（B幣）（總）", totalBCoin],
        [
          "藍新扣手續費（總） - 支付攝影師款（總）",
          Math.round(totalNet - totalPayPhotographer),
        ],
        [
          "收入（總） - 手續費（總）",
          Math.round(totalPlatformIncome - totalFee),
        ],
      ];

      const dataRows = rows.map((r) => headers.map((h) => r[h] ?? ""));
      const ws1 = XLSX.utils.aoa_to_sheet([headers, ...dataRows]);

      const ws2 = XLSX.utils.aoa_to_sheet([
        ["項目", "金額"],
        ...summaryRows.map(([k, v]) => [k, v]),
      ]);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws1, "訂單帳務");
      XLSX.utils.book_append_sheet(wb, ws2, "彙總總表");
      XLSX.writeFile(wb, "訂單帳務與總表.xlsx");

      showSnackbar("Excel 已下載", "success");
    } catch (e) {
      console.error(e);
      showSnackbar(e.message || "匯出失敗", "error");
    }
  };
  return (
    <>
      <Header />
      <LeftBar />

      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            帳務管理
          </Typography>

          <Box mb={2}>
            <Stack
              direction="row"
              spacing={2}
              alignItems="center"
              flexWrap="wrap"
            >
              <Select
                size="small"
                value={purchaseType}
                onChange={(e) => setPurchaseType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部狀態</MenuItem>
                <MenuItem value="WAIT">等待付款中</MenuItem>
                <MenuItem value="ACCEPT">已付款</MenuItem>
                <MenuItem value="DOING">已接單進行中</MenuItem>
                <MenuItem value="SUCCESS">完成訂單</MenuItem>
                <MenuItem value="CANCEL">取消</MenuItem>
              </Select>

              <DatePicker
                selectsRange
                startDate={startDate}
                endDate={endDate}
                onChange={(update) => setDateRange(update)}
                isClearable
                placeholderText="選擇日期範圍"
              />

              <Button variant="contained" onClick={handleSearch}>
                查詢
              </Button>
              <Button variant="contained" onClick={handleExportExcel}>
                匯出excel
              </Button>

              <span>{`總金額：${totalMoney}`}</span>
              <span>{`總攝影師收益：${totalPhotographerMoney}`}</span>
              {selectedIds.length > 0 && (
                <Button
                  variant="contained"
                  color="success"
                  onClick={handleOpenConfirmBatch}
                >
                  批次標記為已清帳（{selectedIds.length} 筆）
                </Button>
              )}
            </Stack>
          </Box>

          <Table>
            <TableHead>
              <TableRow>
                <TableCell padding="checkbox">
                  <Checkbox
                    indeterminate={
                      selectedIds.length > 0 && selectedIds.length < list.length
                    }
                    checked={
                      list.length > 0 &&
                      selectedIds.length ===
                      list.filter((r) => !r.is_charge).length
                    }
                    onChange={(e) => handleSelectAll(e.target.checked)}
                  />
                </TableCell>
                {[
                  { label: "接單用戶ID", key: "photographer_id" },
                  { label: "接單用戶名稱", key: "photographer.name" },
                  { label: "訂單狀態", key: "purchase_type" },
                  { label: "訂單結案時間", key: "success_time" },
                  { label: "接單者酬勞", key: "photographer_commission" },
                  { label: "金額", key: "total_amount" },
                  { label: "是否清帳", key: "is_charge" },
                  { label: "訂單ID", key: "id" },
                  { label: "標籤", key: "label" },
                  { label: "風格", key: "style" },
                ].map((col) => (
                  <TableCell
                    key={col.key}
                    onClick={() => handleSort(col.key)}
                    sx={{
                      cursor: "pointer",
                      userSelect: "none",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    {col.label}{" "}
                    {sortField === col.key && (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                ))}
                <TableCell>操作</TableCell>
              </TableRow>
            </TableHead>

            <TableBody>
              {list.map((row) => (
                <TableRow key={row.id}>
                  <TableCell padding="checkbox">
                    {!row.is_charge && row.photographer_id !== null && row.purchase_type === "SUCCESS" && (
                      <Checkbox
                        checked={selectedIds.includes(row.id)}
                        onChange={() => handleToggleSelect(row.id)}
                      />
                    )}
                  </TableCell>
                  <TableCell>{row.photographer_id}</TableCell>
                  <TableCell>{row["photographer.name"]}</TableCell>
                  <TableCell>{row.purchase_type}</TableCell>
                  <TableCell>{row.success_time}</TableCell>
                  <TableCell>{row.photographer_commission}</TableCell>
                  <TableCell>{row.total_amount}</TableCell>
                  <TableCell>{row.is_charge ? "✔️" : "❌"}</TableCell>
                  <TableCell>{row.id}</TableCell>
                  <TableCell>{row.label?.expert_label_name}</TableCell>
                  <TableCell>{row.style?.style_name}</TableCell>
                  <TableCell>
                    <Stack spacing={1} direction="column">
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => handleClickDetail(row)}
                      >
                        查看
                      </Button>
                    </Stack>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>

          <TablePagination
            component="div"
            count={totalCount}
            page={page}
            rowsPerPage={limit}
            onPageChange={(e, newPage) => setPage(newPage)}
            onRowsPerPageChange={(e) => {
              setLimit(parseInt(e.target.value, 10));
              setPage(0);
            }}
          />
        </Paper>

        {/* Dialog 保留 */}
        <Dialog open={dialogOpen} onClose={handleCloseDialog} fullWidth>
          <DialogTitle>銀行帳戶詳情</DialogTitle>
          <DialogContent dividers>
            {selectedRow && (
              <Box>
                <Typography>銀行代碼：{selectedRow.bank_name}</Typography>
                <Typography>分行名稱：{selectedRow.bank_sub}</Typography>
                <Typography>帳戶名稱：{selectedRow.bank}</Typography>
                <Typography>
                  收款帳號：<b>{selectedRow.bank_account}</b>
                </Typography>
              </Box>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCloseDialog}>關閉</Button>
          </DialogActions>
        </Dialog>

        {/* 批次清帳確認 */}
        <Dialog open={confirmBatchOpen} onClose={handleCloseConfirmBatch}>
          <DialogTitle>確認批次清帳</DialogTitle>
          <DialogContent dividers>
            <Stack spacing={2}>
              <Typography>
                是否要將這 {selectedIds.length} 筆訂單標記為已清帳？請先選擇清帳的開始與結束時間。
              </Typography>
              <DatePicker
                selectsRange
                startDate={batchStartDate}
                endDate={batchEndDate}
                onChange={(update) => setBatchDateRange(update)}
                shouldCloseOnSelect={false}
                inline
              />
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCloseConfirmBatch}>取消</Button>
            <Button
              onClick={handleSubmitBatch}
              variant="contained"
              color="success"
            >
              確定
            </Button>
          </DialogActions>
        </Dialog>

        <Snackbar
          open={snackbarOpen}
          autoHideDuration={3000}
          onClose={handleCloseSnackbar}
          anchorOrigin={{ vertical: "top", horizontal: "center" }}
        >
          <Alert
            severity={snackbarSeverity}
            onClose={handleCloseSnackbar}
            sx={{ width: "100%" }}
          >
            {snackbarMsg}
          </Alert>
        </Snackbar>
      </Container>
    </>
  );
};

export default FinanceManagement;
