import { createTheme, ThemeProvider } from "@mui/material";
import "react-datepicker/dist/react-datepicker.css";
import { Route, BrowserRouter as Router, Routes } from "react-router-dom";
import { GlobalStyle, ResetStyle } from "./components/globalStyle";
import Business from "./containers/Admin/Business";
import Label from "./containers/Admin/Label";
import Member from "./containers/Admin/Member";
import Order from "./containers/Admin/Order";
import PaymentRecord from "./containers/Admin/PaymentRecord";
import Setting from "./containers/Admin/Setting";
import Login from "./containers/Login";



import OverView from "./containers/Member/OverView";

function App() {
  const theme = createTheme({
    components: {
      MuiOutlinedInput: {
        styleOverrides: {
          notchedOutline: {
            border: "1px solid #fff",
            borderRadius: "100px",
            backgroundColor: "#fff",
            zIndex: -1,
          },
        },
      },
      MuiDialog: {
        styleOverrides: {
          paper: ({ theme }) => ({
            borderRadius: 18,
            border: "1px solid rgba(15, 23, 42, 0.08)",
            boxShadow: "0 20px 50px rgba(15, 23, 42, 0.2)",
            backgroundImage:
              "linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,250,252,0.98) 100%)",
            margin: theme.spacing(1.5),
            width: "calc(100% - 24px)",
            maxWidth: 920,
            overflow: "hidden",
            "& .MuiDialogTitle-root": {
              padding: "18px 20px 10px",
              fontSize: 18,
              fontWeight: 700,
              color: "#1f2937",
            },
            "& .MuiDialogContent-root": {
              padding: "16px 20px",
              maxWidth: "100%",
              width: "auto !important",
            },
            "& .MuiDialogActions-root": {
              padding: "12px 20px 20px",
              gap: 8,
              flexWrap: "wrap",
              justifyContent: "flex-end",
            },
            [theme.breakpoints.down("sm")]: {
              margin: theme.spacing(1),
              width: "calc(100% - 16px)",
              borderRadius: 14,
              "& .MuiDialogTitle-root": {
                fontSize: 16,
                padding: "14px 14px 8px",
              },
              "& .MuiDialogContent-root": {
                padding: "12px 14px",
              },
              "& .MuiDialogActions-root": {
                padding: "10px 14px 14px",
                justifyContent: "stretch",
              },
            },
          }),
          paperFullWidth: {
            width: "calc(100% - 24px)",
            maxWidth: 920,
          },
        },
      },
      MuiDialogContent: {
        styleOverrides: {
          root: {
            overflowX: "hidden",
          },
        },
      },
      MuiButton: {
        styleOverrides: {
          root: {
            width: "120px",
          },
          containedPrimary: {
            backgroundColor: "#8C9EFF",
            borderRadius: "100px",
            width: 120,
            height: 40,
            fontSize: 14,
            boxShadow: "none",
            "&.Mui-disabled": {
              backgroundColor: "#D7E0FF",
              color: "#fff",
            },
          },
          outlinedPrimary: {
            color: "#A7A7A7",
            borderColor: "#A7A7A7",
          },
          outlined: {
            borderRadius: "100px",
            width: 120,
            height: 40,
            fontSize: 14,
            boxShadow: "none",
          },
        },
      },
      MuiTableRow: {
        styleOverrides: {
          head: {
            height: 80,
          },
        },
      },
      MuiTableCell: {
        styleOverrides: {
          head: {
            color: "#505050",
          },
          body: {
            color: "#7C7C7C",
            height: 80,
          },
        },
      },
      MuiRadio: {
        styleOverrides: {
          colorPrimary: {
            color: "#8C9EFF",
            "&.Mui-checked": {
              color: "#8C9EFF",
            },
          },
        },
      },
      MuiFormControlLabel: {
        styleOverrides: {
          label: {
            color: "#505050",
          },
        },
      },
      MuiAlert: {
        styleOverrides: {
          standard: {
            alignItems: "center",
            fontSize: "14px",
          },
        },
      },
    },
  });

  return (
    <ThemeProvider theme={theme}>
        <div className="App">
          <ResetStyle />
          <GlobalStyle />
          <Router>
            <Routes>
              <Route element={<Setting />} path={"/setting"} />
              <Route element={<Label />} path={"/label"} />
              <Route element={<Member />} path={"/member"} />
              <Route element={<Order />} path={"/order"} />
              <Route element={<PaymentRecord />} path={"/payment-record"} />
              <Route element={<Business />} path={"/business"} />
            </Routes>
            <Routes>
              <Route element={<Login />} path={"/"} />
              <Route element={<OverView />} path={"/OverView"} />
            </Routes>
          </Router>
        </div>
    </ThemeProvider>
  );
}

export default App;
