// api/MemberAPI.js
import { service } from "."; // 路徑依專案調整

/**
 * 1. 取得會員列表 (GET /bo/member)
 *   - 可帶 query 參數：user_id, role_id, keyword, page, limit, order, sort
 */

export const fetchBusinessAccountList = (params = {}) => {
  return new Promise((resolve, reject) => {
    let url = "/bo/member/business?";
    const queryParams = [];

    if (params.user_id) queryParams.push(`user_id=${params.user_id}`);
    if (params.page) queryParams.push(`page=${params.page}`);
    if (params.limit) queryParams.push(`limit=${params.limit}`);
    if (params.order) queryParams.push(`order=${params.order}`);
    if (params.purchase_type)
      queryParams.push(`purchase_type=${params.purchase_type}`);
    if (params.sort) queryParams.push(`sort=${params.sort}`);
    if (params.begin_date) queryParams.push("begin_date=" + params.begin_date);
    if (params.end_date) queryParams.push("end_date=" + params.end_date);
    url += queryParams.join("&");

    service({
      url,
      method: "GET",
    })
      .then((res) => resolve(res.data))
      .catch((err) => reject(err));
  });
};
export const updatePurchaseIsCharge = (purchaseId, isCharge) => {
  return service({
    url: `/bo/purchase/is_charge/${purchaseId}`,
    method: "PUT",
    params: {
      is_charge: isCharge,
    },
  });
};

