export const batchUpdatePurchaseIsCharge = (data  = {}) => {
  return new Promise((resolve, reject) => {
    const today = new Date().toISOString().split("T")[0]; // 取今天 yyyy-mm-dd
    service({
      url: "/bo/purchase/is_charge",
      method: "PUT",
      data: {
        ids:data.ids,
        start_date: today,
        end_date: today,
      },
    })
      .then((res) => resolve(res.data))
      .catch((err) => reject(err));
  });
};
