export const fetchCardTransactions = (params = {}) => {
  return new Promise((resolve, reject) => {
    let url = "/bo/purchase/card_transactions?";
    const queryParams = [];
    const appendQuery = (key, value) => {
      if (value === undefined || value === null || value === "") return;
      queryParams.push(`${key}=${encodeURIComponent(value)}`);
    };

    appendQuery("purchase_id", params.purchase_id);
    appendQuery("merchant_order_no", params.merchant_order_no);
    appendQuery("trade_no", params.trade_no);
    appendQuery("status", params.status);
    appendQuery("trade_status", params.trade_status);
    appendQuery("payment_type", params.payment_type || "CREDIT");
    appendQuery("begin_date", params.begin_date);
    appendQuery("end_date", params.end_date);
    if (params.include_failed === true) {
      appendQuery("include_failed", "true");
    }
    appendQuery("page", params.page);
    appendQuery("limit", params.limit);
    appendQuery("sort", params.sort);
    appendQuery("order", params.order);
    url += queryParams.join("&");

    service({
      url,
      method: "GET",
    })
      .then((res) => resolve(res.data))
      .catch((err) => reject(err));
  });
};

export const reissuePurchaseInvoice = (merchantOrderNo) => {
  return new Promise((resolve, reject) => {
    if (!merchantOrderNo) {
      reject(new Error("merchant_order_no is required"));
      return;
    }

    service({
      url: `/bo/purchase/invoice/reissue/${encodeURIComponent(merchantOrderNo)}`,
      method: "POST",
    })
      .then((res) => resolve(res.data))
      .catch((err) => reject(err));
  });
};

