import {
  Box,
  Checkbox,
  FormControlLabel,
  FormGroup,
  Typography,
} from "@mui/material";
import { useEffect, useState } from "react";
import {
  // 標籤 API：用於取得所有標籤，供攝影師詳情裡的多選
  fetchGroupsAndLabels,
} from "../../../../src/api/Label";
import {
  addMemberCoins,
  fetchMemberCoinLogs,
  // 會員 / 攝影師 相關 API
  fetchMemberList,
  fetchMemberPurchase,
  fetchPhotographerVerifyList,
  reduceMemberCoins,
  updatePhotographerAcceptOrder,
  updatePhotographerData,
  updatePhotographerLabels,
  updatePhotographerVerifyStatus,
  updateMemberVerifyInfo,
  verifyMemberReal,
} from "../../../../src/api/User";

import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

// MUI
import {
  Alert,
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControl,
  InputAdornment,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Switch,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Tabs,
  TextField,
} from "@mui/material";

// 後端狀態對應中文
const statusMap = {
  PENDING: "審核中",
  APPROVED: "通過",
  REJECTED: "被拒絕",
};

const MemberManagement = () => {
  const [tabValue, setTabValue] = useState(0);

  // ───────────────────────────────────────────
  // Snackbar
  // ───────────────────────────────────────────
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const showSnackbar = (message, severity = "info") => {
    setSnackbarMsg(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  const dialogPaperProps = {
    sx: {
      borderRadius: { xs: 2, sm: 3 },
      border: "1px solid rgba(15, 23, 42, 0.08)",
      boxShadow: "0 18px 45px rgba(15, 23, 42, 0.2)",
      background:
        "linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,250,252,0.98) 100%)",
    },
  };
  const dialogTitleSx = {
    pb: 1,
    fontWeight: 700,
    letterSpacing: "0.01em",
  };
  const dialogContentSx = {
    p: { xs: 2, sm: 3 },
    backgroundColor: "#f5f7fb",
  };
  const dialogActionsSx = {
    px: { xs: 2, sm: 3 },
    pb: { xs: 2, sm: 2.5 },
    pt: 1.5,
    gap: 1,
    flexWrap: "wrap",
    position: "sticky",
    bottom: 0,
    backgroundColor: "#f8fafc",
    borderTop: "1px solid #e6eaf0",
    zIndex: 2,
  };
  const detailSectionSx = {
    border: "1px solid #e6eaf0",
    borderRadius: 2.5,
    p: { xs: 1.5, sm: 2.5 },
    backgroundColor: "#fff",
    boxShadow: "0 8px 24px rgba(15, 23, 42, 0.06)",
  };
  const sectionHeaderSx = {
    display: "flex",
    alignItems: "center",
    gap: 1,
    pb: 1,
    mb: 2,
    borderBottom: "1px solid #eef2f7",
  };
  const sectionAccentSx = {
    width: 6,
    height: 20,
    borderRadius: 999,
    background: "linear-gradient(180deg, #4f46e5, #60a5fa)",
  };
  const sectionTitleSx = {
    fontWeight: 700,
    color: "#111827",
  };
  const infoRowSx = {
    display: "grid",
    gridTemplateColumns: { xs: "1fr", sm: "140px 1fr" },
    gap: 1,
    alignItems: "center",
  };
  const sectionGridSx = {
    display: "grid",
    gridTemplateColumns: { xs: "1fr", md: "1fr 1fr" },
    gap: 2,
  };
  const infoLabelSx = { color: "#64748b", fontSize: 13, fontWeight: 600 };
  const infoValueSx = { color: "#111827", fontSize: 14 };
  const statusChipSx = (status) => ({
    display: "inline-flex",
    alignItems: "center",
    px: 1.25,
    py: 0.25,
    borderRadius: 999,
    fontSize: 12,
    fontWeight: 700,
    border: "1px solid",
    backgroundColor:
      status === "APPROVED"
        ? "#ecfdf3"
        : status === "REJECTED"
        ? "#fef2f2"
        : "#f1f5f9",
    color:
      status === "APPROVED"
        ? "#166534"
        : status === "REJECTED"
        ? "#b91c1c"
        : "#475569",
    borderColor:
      status === "APPROVED"
        ? "#bbf7d0"
        : status === "REJECTED"
        ? "#fecaca"
        : "#e2e8f0",
  });
  const imageGridSx = {
    display: "grid",
    gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
    gap: 2,
  };
  const imageCardSx = {
    border: "1px solid #e6eaf0",
    borderRadius: 2,
    p: 1.5,
    backgroundColor: "#f8fafc",
  };
  const previewImageStyle = {
    width: "100%",
    maxWidth: "260px",
    marginTop: 6,
    borderRadius: 10,
    border: "1px solid #e5e7eb",
    objectFit: "cover",
  };
  // 排序用 state
  const [memberSortField, setMemberSortField] = useState("id");
  const [memberSortOrder, setMemberSortOrder] = useState("asc");
  const [photographerSortField, setPhotographerSortField] = useState("id");
  const [photographerSortOrder, setPhotographerSortOrder] = useState("asc");
  // ───────────────────────────────────────────
  // 一、一般會員
  // ───────────────────────────────────────────
  const [memberPage, setMemberPage] = useState(0);
  const [memberLimit, setMemberLimit] = useState(10);
  const [memberTotalCount, setMemberTotalCount] = useState(0);

  const [memberKeyword, setMemberKeyword] = useState("");
  const [memberList, setMemberList] = useState([]);
  const handleCheckboxChange = (event, labelId) => {
    if (event.target.checked) {
      setSelectedLabelIds((prev) => [...prev, labelId]);
    } else {
      setSelectedLabelIds((prev) => prev.filter((id) => id !== labelId));
    }
  };
  // B 幣配發
  const [openCoinDialog, setOpenCoinDialog] = useState(false);
  const [coinMemberId, setCoinMemberId] = useState(null);
  const [coinAmount, setCoinAmount] = useState(0);

  // 訂單列表
  const [openPurchaseDialog, setOpenPurchaseDialog] = useState(false);
  const [purchaseData, setPurchaseData] = useState([]);
  const [purchaseMemberId, setPurchaseMemberId] = useState(null);

  // 會員詳情
  const [openMemberDetailDialog, setOpenMemberDetailDialog] = useState(false);
  const [memberDetailData, setMemberDetailData] = useState(null);
  const [memberVerifyForm, setMemberVerifyForm] = useState({
    phone: "",
    id_card: "",
    birthday: "",
  });

  // 1.1 取得會員列表
  const getMembers = async () => {
    try {
      const pageIndex = memberPage + 1;
      const res = await fetchMemberList({
        page: pageIndex,
        limit: memberLimit,
        keyword: memberKeyword,
        order: memberSortOrder,
        sort: memberSortField,
      });
      if (res?.success) {
        const records = res.data?.records || [];
        setMemberList(records);

        const pageObj = res.data?.page || {};
        setMemberTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得會員列表失敗", "error");
      }
    } catch (error) {
      console.error("getMembers error:", error);
      showSnackbar("取得會員列表錯誤", "error");
    }
  };

  // 分頁操作
  const handleChangeMemberPage = (e, newPage) => {
    setMemberPage(newPage);
  };
  const handleChangeMemberRowsPerPage = (e) => {
    setMemberLimit(parseInt(e.target.value, 10));
    setMemberPage(0);
  };

  // 審核會員實名
  const handleVerifyMemberReal = (userId, status) => {
    verifyMemberReal(userId, status)
      .then((res) => {
        if (res?.success) {
          showSnackbar("審核成功", "success");
          getMembers();
        } else {
          showSnackbar("審核失敗", "error");
        }
      })
      .catch((err) => {
        console.error("verifyMemberReal error:", err);
        showSnackbar("審核錯誤", "error");
      });
  };

  // 配發 B 幣
  const [coinAction, setCoinAction] = useState("add"); // 預設是配發

  const handleOpenCoinDialog = (memberId) => {
    setCoinMemberId(memberId);
    setCoinAmount(0);
    setOpenCoinDialog(true);
    setCoinAction("add");
  };
  const handleCloseCoinDialog = () => {
    setOpenCoinDialog(false);
    setCoinMemberId(null);
  };
  const handleAddMemberCoins = () => {
    if (!coinMemberId || coinAmount <= 0) {
      showSnackbar("請輸入正確的 B 幣數量", "warning");
      return;
    }
    addMemberCoins({ user_id: coinMemberId, bigtime_coin: coinAmount })
      .then((res) => {
        if (res?.success) {
          showSnackbar("配發成功", "success");
          handleCloseCoinDialog();
          getMembers();
        } else {
          showSnackbar("配發失敗", "error");
        }
      })
      .catch((err) => {
        console.error("addMemberCoins error:", err);
        showSnackbar("配發錯誤", "error");
      });
  };
  const handleReduceMemberCoins = () => {
    if (!coinMemberId || coinAmount <= 0) {
      showSnackbar("請輸入正確的 B 幣數量", "warning");
      return;
    }
    reduceMemberCoins({ user_id: coinMemberId, bigtime_coin: coinAmount })
      .then((res) => {
        if (res?.success) {
          showSnackbar("扣除成功", "success");
          handleCloseCoinDialog();
          getMembers();
        } else {
          showSnackbar("扣除失敗", "error");
        }
      })
      .catch((err) => {
        console.error("reduceMemberCoins error:", err);
        showSnackbar("配發錯誤", "error");
      });
  };
  // 查看訂單
  const handleOpenPurchaseDialog = (memberId) => {
    setPurchaseMemberId(memberId);
    setPurchaseData([]);
    setOpenPurchaseDialog(true);

    fetchMemberPurchase({ user_id: memberId, page: 1, limit: 10 })
      .then((res) => {
        if (res?.success) {
          const records = res.data?.records || [];
          setPurchaseData(records);
        } else {
          showSnackbar("取得訂單失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberPurchase error:", err);
        showSnackbar("取得訂單錯誤", "error");
      });
  };
  const handleClosePurchaseDialog = () => {
    setOpenPurchaseDialog(false);
    setPurchaseMemberId(null);
    setPurchaseData([]);
  };

  // 會員詳情
  const handleOpenMemberDetail = (m) => {
    setMemberDetailData(m);
    setMemberVerifyForm({
      phone: m?.phone || "",
      id_card: m?.id_card || "",
      birthday: m?.birthday || "",
    });
    setOpenMemberDetailDialog(true);
  };
  const handleCloseMemberDetail = () => {
    setOpenMemberDetailDialog(false);
    setMemberDetailData(null);
    setMemberVerifyForm({ phone: "", id_card: "", birthday: "" });
  };

  // 搜尋會員
  const handleSearchMembers = () => {
    setMemberPage(0);
    getMembers();
  };

  // ───────────────────────────────────────────
  // 二、攝影師
  // ───────────────────────────────────────────
  const [photographerPage, setPhotographerPage] = useState(0);
  const [photographerLimit, setPhotographerLimit] = useState(10);
  const [photographerTotalCount, setPhotographerTotalCount] = useState(0);

  const [photographerKeyword, setPhotographerKeyword] = useState("");
  const [photographerList, setPhotographerList] = useState([]);

  // 攝影師詳情
  const [openPhotographerDetailDialog, setOpenPhotographerDetailDialog] =
    useState(false);
  const [photographerDetailData, setPhotographerDetailData] = useState(null);
  const [photographerVerifyForm, setPhotographerVerifyForm] = useState({
    phone: "",
    id_card: "",
    birthday: "",
  });

  // 從標籤API取回的所有標籤
  const [allLabels, setAllLabels] = useState([]);
  // 在攝影師詳情中要更新的值
  const [selectedLabelIds, setSelectedLabelIds] = useState([]);
  const [workUrl, setWorkUrl] = useState("");
  const [photoUrl, setPhotoUrl] = useState("");
  const createEmptyAddress = () => ({ addr: "", lat: "", lng: "" });
  const [photographerAddresses, setPhotographerAddresses] = useState([
    createEmptyAddress(),
  ]);

  // 2.1 取得攝影師列表
  const getPhotographers = async () => {
    try {
      const pageIndex = photographerPage + 1;
      const res = await fetchPhotographerVerifyList({
        page: pageIndex,
        limit: photographerLimit,
        keyword: photographerKeyword,
        order: photographerSortOrder,
        sort: photographerSortField,
      });
      if (res?.success) {
        const records = res.data?.records || [];
        setPhotographerList(records);

        const pageObj = res.data?.page || {};
        setPhotographerTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得攝影師列表失敗", "error");
      }
    } catch (error) {
      console.error("getPhotographers error:", error);
      showSnackbar("取得攝影師列表錯誤", "error");
    }
  };
  // 排序函式
  const handleMemberSort = (field) => {
    if (memberSortField === field) {
      setMemberSortOrder(memberSortOrder === "asc" ? "desc" : "asc");
    } else {
      setMemberSortField(field);
      setMemberSortOrder("asc");
    }
  };
  // 加上排序觸發 useEffect
  useEffect(() => {
    if (tabValue === 0) getMembers();
  }, [tabValue, memberPage, memberLimit, memberSortField, memberSortOrder]);

  useEffect(() => {
    if (tabValue === 1) getPhotographers();
  }, [
    tabValue,
    photographerPage,
    photographerLimit,
    photographerSortField,
    photographerSortOrder,
  ]);

  const handlePhotographerSort = (field) => {
    if (photographerSortField === field) {
      setPhotographerSortOrder(
        photographerSortOrder === "asc" ? "desc" : "asc"
      );
    } else {
      setPhotographerSortField(field);
      setPhotographerSortOrder("asc");
    }
  };

  // 攝影師分頁
  const handleChangePhotographerPage = (e, newPage) => {
    setPhotographerPage(newPage);
  };
  const handleChangePhotographerRowsPerPage = (e) => {
    setPhotographerLimit(parseInt(e.target.value, 10));
    setPhotographerPage(0);
  };

  // 審核攝影師
  const handleUpdatePhotographerStatus = (user_id, status) => {
    updatePhotographerVerifyStatus({ user_id, status })
      .then((res) => {
        if (res?.success) {
          showSnackbar("審核攝影師成功", "success");
          getPhotographers();
        } else {
          showSnackbar("審核攝影師失敗", "error");
        }
      })
      .catch((err) => {
        console.error("handleUpdatePhotographerStatus error:", err);
        showSnackbar("審核攝影師錯誤", "error");
      });
  };

  // 打開攝影師詳情 (預先帶入作品url/相簿url與標籤)
  const handleOpenPhotographerDetail = (ph) => {
    setPhotographerDetailData(ph);

    // 預先帶入
    setWorkUrl(ph.work_url || "");
    setPhotoUrl(ph.photo_url || "");
    setPhotographerVerifyForm({
      phone: ph?.phone || "",
      id_card: ph?.national_id || ph?.id_card || "",
      birthday: ph?.birthday || "",
    });

    // 預先勾選標籤
    const currentLabels = ph.label_responses || [];
    const labelIds = currentLabels.map((lb) => lb.label_id);
    console.log(labelIds);
    setSelectedLabelIds(labelIds);

    const addrList =
      ph.addr_responses?.length > 0
        ? ph.addr_responses.map((addr) => ({
            addr: addr.addr || "",
            lat:
              addr.lat !== undefined && addr.lat !== null
                ? String(addr.lat)
                : "",
            lng:
              addr.lng !== undefined && addr.lng !== null
                ? String(addr.lng)
                : "",
          }))
        : [createEmptyAddress()];
    setPhotographerAddresses(addrList);

    setOpenPhotographerDetailDialog(true);
  };
  const handleClosePhotographerDetail = () => {
    setOpenPhotographerDetailDialog(false);
    setPhotographerDetailData(null);
    setWorkUrl("");
    setPhotoUrl("");
    setSelectedLabelIds([]);
    setPhotographerAddresses([createEmptyAddress()]);
    setPhotographerVerifyForm({ phone: "", id_card: "", birthday: "" });
  };

  // 攝影師多選標籤
  const handleChangeSelectLabels = (e) => {
    const value = e.target.value;
    setSelectedLabelIds(typeof value === "string" ? value.split(",") : value);
  };

  const handleAddressFieldChange = (index, field, value) => {
    setPhotographerAddresses((prev) =>
      prev.map((item, idx) =>
        idx === index
          ? {
              ...item,
              [field]: value,
            }
          : item
      )
    );
  };

  const handleAddAddressRow = () => {
    setPhotographerAddresses((prev) => [...prev, createEmptyAddress()]);
  };

  const handleRemoveAddressRow = (index) => {
    setPhotographerAddresses((prev) => {
      if (prev.length === 1) return prev;
      return prev.filter((_, idx) => idx !== index);
    });
  };

  // 同時更新標籤與作品

  const handleUpdatePhotographerAll = async () => {
    try {
      if (!photographerDetailData) return;
      const userId = photographerDetailData.id;

      const addrRequests = [];
      for (let i = 0; i < photographerAddresses.length; i += 1) {
        const item = photographerAddresses[i];
        const addrText = (item.addr || "").trim();
        const latText = (item.lat || "").trim();
        const lngText = (item.lng || "").trim();

        if (!addrText && !latText && !lngText) {
          continue;
        }

        if (!addrText || !latText || !lngText) {
          showSnackbar(
            `\u8acb\u5b8c\u6574\u586b\u5beb\u7b2c ${i + 1} \u7b46\u53ef\u670d\u52d9\u5730\u9ede`,
            "warning"
          );
          return;
        }

        const latNumber = Number(latText);
        const lngNumber = Number(lngText);
        if (Number.isNaN(latNumber) || Number.isNaN(lngNumber)) {
          showSnackbar(
            `\u8acb\u8f38\u5165\u6b63\u78ba\u7684\u7d93\u7def\u5ea6\u683c\u5f0f\uff08\u7b2c ${i + 1} \u7b46\uff09`,
            "warning"
          );
          return;
        }

        addrRequests.push({
          addr: addrText,
          lat: latNumber,
          lng: lngNumber,
        });
      }

      if (selectedLabelIds.length === 0) {
        showSnackbar("\u8acb\u81f3\u5c11\u9078\u64c7\u4e00\u500b\u6a19\u7c64", "warning");
        return;
      }

      const labelString = selectedLabelIds.join(",");
      const resLabel = await updatePhotographerLabels(userId, {
        expert_label_ids: labelString,
      });
      if (!resLabel?.success) {
        showSnackbar("\u66f4\u65b0\u6a19\u7c64\u5931\u6557", "error");
        return;
      }

      const updatePayload = {
        work_url: workUrl,
        photo_url: photoUrl,
      };
      if (addrRequests.length > 0) {
        updatePayload.addr_requests = addrRequests;
      }

      const resPhoto = await updatePhotographerData(userId, updatePayload);
      if (!resPhoto?.success) {
        showSnackbar("\u66f4\u65b0\u4f5c\u54c1\u8cc7\u8a0a\u5931\u6557", "error");
        return;
      }

      showSnackbar("\u66f4\u65b0\u6210\u529f", "success");
      handleClosePhotographerDetail();
      getPhotographers();
    } catch (error) {
      console.error("handleUpdatePhotographerAll error:", error);
      showSnackbar("\u66f4\u65b0\u5931\u6557", "error");
    }
  };
;

  const handleUpdateVerifyInfo = async (userId, formData) => {
    if (!userId) return;
    const payload = {
      phone: (formData.phone || "").trim(),
      id_card: (formData.id_card || "").trim(),
      birthday: (formData.birthday || "").trim(),
    };
    if (!payload.phone || !payload.id_card || !payload.birthday) {
      showSnackbar("請完整填寫生日、身分證、電話", "warning");
      return;
    }

    try {
      const res = await updateMemberVerifyInfo(userId, payload);
      if (res?.success) {
        showSnackbar("✅ 實名資料更新成功", "success");
        if (tabValue === 0) getMembers();
        if (tabValue === 1) getPhotographers();
      } else {
        showSnackbar(res?.message || "❌ 實名資料更新失敗", "error");
      }
    } catch (err) {
      console.error("updateMemberVerifyInfo error:", err);
      showSnackbar("❌ 實名資料更新發生錯誤", "error");
    }
  };

  // 搜尋攝影師
  const handleSearchPhotographers = () => {
    setPhotographerPage(0);
    getPhotographers();
  };

  // ───────────────────────────────────────────
  // 載入所有標籤
  // ───────────────────────────────────────────
  const getAllLabels = async () => {
    try {
      const res = await fetchGroupsAndLabels();
      if (res?.success) {
        /*const groupArray = res.data || [];
        const arr = [];
        groupArray.forEach((g) => {
          (g.label_responses || []).forEach((lb) => {
            arr.push({
              label_id: lb.label_id,
              label_name: lb.label,
              group_id: g.group_id,
              group_name: g.group,
            });
          });
        });
        setAllLabels(arr);*/
        setAllLabels(res.data);
      }
    } catch (error) {
      console.error("getAllLabels error:", error);
    }
  };

  const dynamicLabels = allLabels.flatMap((g) => g.dynamic_response || []);

  const staticLabels = allLabels.flatMap((g) => g.flat_response || []);

  // ───────────────────────────────────────────
  // useEffect
  // ───────────────────────────────────────────
  useEffect(() => {
    // 一開始就抓所有標籤 (供攝影師詳情使用)
    getAllLabels();
  }, []);

  // 如果在「一般會員」分頁，page/limit 改變就抓會員
  useEffect(() => {
    if (tabValue === 0) {
      getMembers();
    }
  }, [tabValue, memberPage, memberLimit]);

  // 如果在「攝影師」分頁，page/limit 改變就抓攝影師
  useEffect(() => {
    if (tabValue === 1) {
      getPhotographers();
    }
  }, [tabValue, photographerPage, photographerLimit]);

  // ───────────────────────────────────────────
  // Render
  // ───────────────────────────────────────────
  const handleChangeTab = (e, newVal) => {
    setTabValue(newVal);
  };
  const [openCoinLogDialog, setOpenCoinLogDialog] = useState(false);
  const [coinLogMemberId, setCoinLogMemberId] = useState(null);
  const [coinLogList, setCoinLogList] = useState([]);
  const [coinLogPage, setCoinLogPage] = useState(0);
  const [coinLogLimit, setCoinLogLimit] = useState(10);
  const [coinLogTotalCount, setCoinLogTotalCount] = useState(0);

  const handleOpenCoinLogDialog = (userId) => {
    setCoinLogMemberId(userId);
    setOpenCoinLogDialog(true);
    fetchMemberCoinLogs({
      user_id: userId,
      page: 1,
      limit: coinLogLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage((res.data.page.current_page || 1) - 1);
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };
  const handleChangeCoinLogPage = (event, newPage) => {
    const pageIndex = newPage + 1; // 後端從 1 開始

    fetchMemberCoinLogs({
      user_id: coinLogMemberId,
      page: pageIndex,
      limit: coinLogLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage(newPage); // 注意：這裡是 newPage，不用再 -1
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };

  const handleChangeCoinLogRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setCoinLogLimit(newLimit);
    setCoinLogPage(0);

    fetchMemberCoinLogs({
      user_id: coinLogMemberId,
      page: 1,
      limit: newLimit,
      order: "desc",
      sort: "id",
    })
      .then((res) => {
        if (res?.success) {
          setCoinLogList(res.data.records);
          setCoinLogPage(0);
          setCoinLogTotalCount(res.data.page.total_count || 0);
        } else {
          showSnackbar("取得 B 幣紀錄失敗", "error");
        }
      })
      .catch((err) => {
        console.error("fetchMemberCoinLogs error:", err);
        showSnackbar("取得 B 幣紀錄錯誤", "error");
      });
  };

  const handleCloseCoinLogDialog = () => {
    setOpenCoinLogDialog(false);
    setCoinLogList([]);
    setCoinLogMemberId(null);
  };
  const handleToggleAcceptOrder = (userId, isAccept) => {
    updatePhotographerAcceptOrder(userId, isAccept)
      .then((res) => {
        if (res?.success) {
          showSnackbar("接單狀態已更新", "success");
          getPhotographers(); // 重新取得列表，刷新開關狀態
        } else {
          showSnackbar("更新失敗", "error");
        }
      })
      .catch((err) => {
        console.error("updatePhotographerAcceptOrder error:", err);
        showSnackbar("更新錯誤", "error");
      });
  };
  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            會員管理
          </Typography>
          <Tabs value={tabValue} onChange={handleChangeTab} sx={{ mb: 3 }}>
            <Tab label="一般會員" />
            <Tab label="攝影師" />
          </Tabs>

          {/* ─────────────────────────────────────────────────────────────
              一般會員
             ───────────────────────────────────────────────────────────── */}
          {tabValue === 0 && (
            <Paper sx={{ p: 2 }}>
              {/* 搜尋 */}
              <Box mb={2} display="flex" alignItems="center" gap={2}>
                <TextField
                  size="small"
                  placeholder="搜尋關鍵字"
                  value={memberKeyword}
                  onChange={(e) => setMemberKeyword(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start"></InputAdornment>
                    ),
                  }}
                />
                <Button variant="contained" onClick={handleSearchMembers}>
                  搜尋
                </Button>
              </Box>

              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell
                        onClick={() => handleMemberSort("id")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        會員ID{" "}
                        {memberSortField === "id" &&
                          (memberSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handleMemberSort("name")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        姓名{" "}
                        {memberSortField === "name" &&
                          (memberSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handleMemberSort("phone")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        電話{" "}
                        {memberSortField === "phone" &&
                          (memberSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handleMemberSort("real_status")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        實名狀態{" "}
                        {memberSortField === "real_status" &&
                          (memberSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {memberList.map((m) => {
                      const statusLabel =
                        statusMap[m.real_status] || m.real_status;
                      return (
                        <TableRow key={m.id}>
                          <TableCell>{m.id}</TableCell>
                          <TableCell>{m.name}</TableCell>
                          <TableCell>{m.phone}</TableCell>
                          <TableCell>{statusLabel}</TableCell>
                          <TableCell align="center">
                            <Stack
                              direction="row"
                              spacing={1}
                              justifyContent="center"
                            >
                              {/* 詳情 */}
                              <Button
                                variant="outlined"
                                onClick={() => handleOpenMemberDetail(m)}
                              >
                                詳情
                              </Button>
                              {/* 審核 (僅 PENDING) */}
                              {m.real_status === "PENDING" && (
                                <>
                                  <Button
                                    variant="outlined"
                                    onClick={() =>
                                      handleVerifyMemberReal(m.id, "APPROVED")
                                    }
                                  >
                                    通過
                                  </Button>
                                  <Button
                                    variant="outlined"
                                    color="warning"
                                    onClick={() =>
                                      handleVerifyMemberReal(m.id, "REJECTED")
                                    }
                                  >
                                    駁回
                                  </Button>
                                </>
                              )}
                              {/* 配發 B 幣 */}
                              <Button
                                variant="contained"
                                onClick={() => handleOpenCoinDialog(m.id)}
                              >
                                配發B幣
                              </Button>
                              {/* 查看訂單 */}
                              <Button
                                variant="outlined"
                                onClick={() => handleOpenPurchaseDialog(m.id)}
                              >
                                訂單
                              </Button>
                              <Button
                                variant="outlined"
                                onClick={() => handleOpenCoinLogDialog(m.id)}
                              >
                                B幣紀錄
                              </Button>
                            </Stack>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                    {memberList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={5} align="center">
                          目前沒有會員資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>

              <TablePagination
                component="div"
                count={memberTotalCount}
                page={memberPage}
                onPageChange={handleChangeMemberPage}
                rowsPerPage={memberLimit}
                onRowsPerPageChange={handleChangeMemberRowsPerPage}
              />
            </Paper>
          )}

          {/* ─────────────────────────────────────────────────────────────
              攝影師
             ───────────────────────────────────────────────────────────── */}
          {tabValue === 1 && (
            <Paper sx={{ p: 2 }}>
              <Box mb={2} display="flex" alignItems="center" gap={2}>
                <TextField
                  size="small"
                  placeholder="搜尋關鍵字"
                  value={photographerKeyword}
                  onChange={(e) => setPhotographerKeyword(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start"></InputAdornment>
                    ),
                  }}
                />
                <Button variant="contained" onClick={handleSearchPhotographers}>
                  搜尋
                </Button>
              </Box>

              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell
                        onClick={() => handlePhotographerSort("id")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        攝影師ID{" "}
                        {photographerSortField === "id" &&
                          (photographerSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handlePhotographerSort("firstname")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        姓名{" "}
                        {photographerSortField === "firstname" &&
                          (photographerSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handlePhotographerSort("phone")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        電話{" "}
                        {photographerSortField === "phone" &&
                          (photographerSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell
                        onClick={() => handlePhotographerSort("status")}
                        sx={{
                          cursor: "pointer",
                          "&:hover": {
                            backgroundColor: "#f5f5f5",
                          },
                        }}
                      >
                        審核狀態{" "}
                        {photographerSortField === "status" &&
                          (photographerSortOrder === "asc" ? "↑" : "↓")}
                      </TableCell>
                      <TableCell>審核權限</TableCell>
                      <TableCell align="center">操作</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {photographerList.map((ph) => {
                      const statusLabel = statusMap[ph.status] || ph.status;
                      const fullName = `${ph.firstname || ""}${
                        ph.lastname || ""
                      }`;
                      return (
                        <TableRow key={ph.id}>
                          <TableCell>{ph.id}</TableCell>
                          <TableCell>{fullName}</TableCell>
                          <TableCell>{ph.phone}</TableCell>
                          <TableCell>{statusLabel}</TableCell>
                          <TableCell>
                            <FormControlLabel
                              control={
                                <Switch
                                  checked={ph.is_accept_order_back}
                                  onChange={(e) =>
                                    handleToggleAcceptOrder(
                                      ph.id,
                                      e.target.checked
                                    )
                                  }
                                />
                              }
                              label="接單"
                            />
                          </TableCell>
                          <TableCell align="center">
                            <Stack
                              direction="row"
                              spacing={1}
                              justifyContent="center"
                            >
                              {/* 詳情 */}
                              <Button
                                variant="outlined"
                                onClick={() => handleOpenPhotographerDetail(ph)}
                              >
                                詳情
                              </Button>
                              {/* 審核 (僅 PENDING) */}
                              {ph.status === "PENDING" && (
                                <>
                                  <Button
                                    variant="outlined"
                                    onClick={() =>
                                      handleUpdatePhotographerStatus(
                                        ph.id,
                                        "APPROVED"
                                      )
                                    }
                                  >
                                    通過
                                  </Button>
                                  <Button
                                    variant="outlined"
                                    color="warning"
                                    onClick={() =>
                                      handleUpdatePhotographerStatus(
                                        ph.id,
                                        "REJECTED"
                                      )
                                    }
                                  >
                                    駁回
                                  </Button>
                                </>
                              )}
                            </Stack>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                    {photographerList.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={5} align="center">
                          目前沒有攝影師資料
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>

              <TablePagination
                component="div"
                count={photographerTotalCount}
                page={photographerPage}
                onPageChange={handleChangePhotographerPage}
                rowsPerPage={photographerLimit}
                onRowsPerPageChange={handleChangePhotographerRowsPerPage}
              />
            </Paper>
          )}

          {/* ──────────────────────────────────────────
            以下為各種 Dialog
           ────────────────────────────────────────── */}

          {/* 配發 / 扣除 B 幣 */}
          <Dialog
            open={openCoinDialog}
            onClose={handleCloseCoinDialog}
            fullWidth
            maxWidth="xs"
            PaperProps={dialogPaperProps}
          >
            <DialogTitle sx={dialogTitleSx}>B 幣操作</DialogTitle>
            <DialogContent dividers sx={dialogContentSx}>
              <Box sx={detailSectionSx}>
                <Typography sx={sectionTitleSx}>會員ID</Typography>
                <Typography sx={infoValueSx}>{coinMemberId}</Typography>

                {/* 選擇操作模式 */}
                <FormControl fullWidth sx={{ mt: 2 }}>
                  <InputLabel>操作方式</InputLabel>
                  <Select
                    value={coinAction}
                    label="操作方式"
                    onChange={(e) => setCoinAction(e.target.value)}
                  >
                    <MenuItem value="add">配發</MenuItem>
                    <MenuItem value="reduce">扣除</MenuItem>
                  </Select>
                </FormControl>

                {/* 輸入金額 */}
                <TextField
                  fullWidth
                  sx={{ mt: 2 }}
                  type="number"
                  label="B 幣數量"
                  value={coinAmount}
                  onChange={(e) => setCoinAmount(e.target.value)}
                />
              </Box>
            </DialogContent>
            <DialogActions sx={dialogActionsSx}>
              <Button onClick={handleCloseCoinDialog} variant="outlined">
                取消
              </Button>
              <Button
                variant="contained"
                color={coinAction === "reduce" ? "error" : "primary"}
                onClick={
                  coinAction === "reduce"
                    ? handleReduceMemberCoins
                    : handleAddMemberCoins
                }
                sx={{ ml: { xs: 0, sm: 1 } }}
              >
                確定
              </Button>
            </DialogActions>
          </Dialog>

          {/* 訂單列表 */}
          <Dialog
            open={openPurchaseDialog}
            onClose={handleClosePurchaseDialog}
            fullWidth
            maxWidth="md"
            PaperProps={dialogPaperProps}
          >
            <DialogTitle sx={dialogTitleSx}>
              訂單列表 (會員ID: {purchaseMemberId})
            </DialogTitle>
            <DialogContent dividers sx={dialogContentSx}>
              {purchaseData.length === 0 ? (
                <Box sx={detailSectionSx}>
                  <Typography sx={infoValueSx}>暫無訂單資料</Typography>
                </Box>
              ) : (
                <TableContainer
                  sx={{
                    border: "1px solid #e6eaf0",
                    borderRadius: 2.5,
                    backgroundColor: "#fff",
                    overflowX: "auto",
                  }}
                >
                  <Table size="small">
                    <TableHead
                      sx={{
                        backgroundColor: "#f1f5f9",
                        "& th": { color: "#0f172a", fontWeight: 700 },
                      }}
                    >
                      <TableRow>
                        <TableCell>訂單ID</TableCell>
                        <TableCell>建立時間</TableCell>
                        <TableCell>標籤</TableCell>
                        <TableCell>金額</TableCell>
                        <TableCell>支付狀態</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {purchaseData.map((order) => (
                        <TableRow key={order.id}>
                          <TableCell>{order.id}</TableCell>
                          <TableCell>{order.create_time}</TableCell>
                          <TableCell>{order.label}</TableCell>
                          <TableCell>{order.total_amount}</TableCell>
                          <TableCell>
                            {order.payment_response?.status}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
            </DialogContent>
            <DialogActions sx={dialogActionsSx}>
              <Button onClick={handleClosePurchaseDialog} variant="outlined">
                關閉
              </Button>
            </DialogActions>
          </Dialog>
          <Dialog
            open={openCoinLogDialog}
            onClose={handleCloseCoinLogDialog}
            fullWidth
            maxWidth="md"
            PaperProps={dialogPaperProps}
          >
            <DialogTitle sx={dialogTitleSx}>
              B 幣紀錄 (會員ID: {coinLogMemberId})
            </DialogTitle>
            <DialogContent dividers sx={dialogContentSx}>
              {coinLogList.length === 0 ? (
                <Box sx={detailSectionSx}>
                  <Typography sx={infoValueSx}>暫無紀錄</Typography>
                </Box>
              ) : (
                <>
                  <TableContainer
                    sx={{
                      border: "1px solid #e6eaf0",
                      borderRadius: 2.5,
                      backgroundColor: "#fff",
                      overflowX: "auto",
                    }}
                  >
                    <Table size="small">
                    <TableHead
                      sx={{
                        backgroundColor: "#f1f5f9",
                        "& th": { color: "#0f172a", fontWeight: 700 },
                      }}
                    >
                        <TableRow>
                          <TableCell>ID</TableCell>
                          <TableCell>建立時間</TableCell>
                          <TableCell>B 幣數量</TableCell>
                          <TableCell>備註</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {coinLogList.map((log) => (
                          <TableRow key={log.id}>
                            <TableCell>{log.id}</TableCell>
                            <TableCell>{log.create_time}</TableCell>
                            <TableCell>{log.bigtime_coin}</TableCell>
                            <TableCell>{log.remark}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>

                  {/* 🔽 分頁元件 */}
                  <TablePagination
                    component="div"
                    count={coinLogTotalCount}
                    page={coinLogPage}
                    rowsPerPage={coinLogLimit}
                    onPageChange={handleChangeCoinLogPage}
                    onRowsPerPageChange={handleChangeCoinLogRowsPerPage}
                  />
                </>
              )}
            </DialogContent>

            <DialogActions sx={dialogActionsSx}>
              <Button onClick={handleCloseCoinLogDialog} variant="outlined">
                關閉
              </Button>
            </DialogActions>
          </Dialog>

          {/* 一般會員詳情 */}
          <Dialog
            open={openMemberDetailDialog}
            onClose={handleCloseMemberDetail}
            fullWidth
            maxWidth="md"
            PaperProps={dialogPaperProps}
          >
            <DialogTitle sx={dialogTitleSx}>👤 會員詳情</DialogTitle>
            <DialogContent dividers sx={dialogContentSx}>
              {memberDetailData ? (
                <Stack spacing={4}>
                  {/* 基本資料 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        基本資料
                      </Typography>
                    </Box>
                    <Box sx={sectionGridSx}>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>會員ID</Typography>
                        <Typography sx={infoValueSx}>
                          {memberDetailData.id}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>B 幣金額</Typography>
                        <Typography sx={infoValueSx}>
                          {memberDetailData.bigtime_coin}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>姓名</Typography>
                        <Typography sx={infoValueSx}>
                          {memberDetailData.name}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>實名狀態</Typography>
                        <Box>
                          <Box sx={statusChipSx(memberDetailData.real_status)}>
                            {statusMap[memberDetailData.real_status] ||
                              memberDetailData.real_status}
                          </Box>
                        </Box>
                      </Box>
                      {memberDetailData.email && (
                        <Box sx={infoRowSx}>
                          <Typography sx={infoLabelSx}>Email</Typography>
                          <Typography sx={infoValueSx}>
                            {memberDetailData.email}
                          </Typography>
                        </Box>
                      )}
                    </Box>

                    <Divider sx={{ my: 2 }} />

                    <Box sx={sectionGridSx}>
                      <TextField
                        label="電話"
                        value={memberVerifyForm.phone}
                        onChange={(e) =>
                          setMemberVerifyForm((prev) => ({
                            ...prev,
                            phone: e.target.value,
                          }))
                        }
                        fullWidth
                      />
                      <TextField
                        label="身分證字號"
                        value={memberVerifyForm.id_card}
                        onChange={(e) =>
                          setMemberVerifyForm((prev) => ({
                            ...prev,
                            id_card: e.target.value,
                          }))
                        }
                        fullWidth
                      />
                      <TextField
                        label="生日"
                        type="date"
                        value={memberVerifyForm.birthday}
                        onChange={(e) =>
                          setMemberVerifyForm((prev) => ({
                            ...prev,
                            birthday: e.target.value,
                          }))
                        }
                        InputLabelProps={{ shrink: true }}
                        helperText="格式：YYYY-MM-DD"
                        fullWidth
                      />
                      <Stack
                        direction={{ xs: "column", sm: "row" }}
                        justifyContent={{ xs: "stretch", sm: "flex-end" }}
                        alignItems="center"
                      >
                        <Button
                          variant="contained"
                          onClick={() =>
                            handleUpdateVerifyInfo(
                              memberDetailData?.id,
                              memberVerifyForm
                            )
                          }
                        >
                          儲存實名資料
                        </Button>
                      </Stack>
                    </Box>

                    {/* 身分證照片 */}
                    {(memberDetailData.file_id_front_url ||
                      memberDetailData.file_id_back_url) && (
                      <Box sx={imageGridSx} mt={2}>
                        {memberDetailData.file_id_front_url && (
                          <Box sx={imageCardSx}>
                            <Typography sx={infoLabelSx}>證件正面</Typography>
                            <img
                              src={memberDetailData.file_id_front_url}
                              alt="front"
                              style={previewImageStyle}
                            />
                          </Box>
                        )}
                        {memberDetailData.file_id_back_url && (
                          <Box sx={imageCardSx}>
                            <Typography sx={infoLabelSx}>證件背面</Typography>
                            <img
                              src={memberDetailData.file_id_back_url}
                              alt="back"
                              style={previewImageStyle}
                            />
                          </Box>
                        )}
                      </Box>
                    )}
                  </Box>

                  {/* 攝影師資料 */}
                  {memberDetailData.photo_response && (
                    <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        攝影師資料
                      </Typography>
                    </Box>
                    <Stack spacing={2}>
                      {(memberDetailData.photo_response.work_url ||
                        memberDetailData.photo_response.photo_url) && (
                        <Box sx={imageGridSx}>
                          {memberDetailData.photo_response.work_url && (
                            <Box sx={imageCardSx}>
                              <Typography sx={infoLabelSx}>作品連結</Typography>
                              <img
                                src={memberDetailData.photo_response.work_url}
                                alt="work"
                                style={previewImageStyle}
                              />
                            </Box>
                          )}
                          {memberDetailData.photo_response.photo_url && (
                            <Box sx={imageCardSx}>
                              <Typography sx={infoLabelSx}>相簿連結</Typography>
                              <img
                                src={memberDetailData.photo_response.photo_url}
                                alt="photo"
                                style={previewImageStyle}
                              />
                            </Box>
                          )}
                        </Box>
                      )}
                      {memberDetailData.label_responses?.length > 0 && (
                        <Box sx={infoRowSx}>
                          <Typography sx={infoLabelSx}>標籤</Typography>
                          <Typography sx={infoValueSx}>
                            {memberDetailData.label_responses
                              .map((lb) => lb.label)
                              .join("、")}
                          </Typography>
                        </Box>
                      )}
                    </Stack>
                    </Box>
                  )}
                </Stack>
              ) : (
                <Typography>無資料</Typography>
              )}
            </DialogContent>
            <DialogActions sx={dialogActionsSx}>
              <Button onClick={handleCloseMemberDetail} variant="outlined">
                關閉
              </Button>
            </DialogActions>
          </Dialog>

          {/* 攝影師詳情 (可同時更新作品URL, 相簿URL, 標籤) */}
          <Dialog
            open={openPhotographerDetailDialog}
            onClose={handleClosePhotographerDetail}
            fullWidth
            maxWidth="md"
            PaperProps={dialogPaperProps}
          >
            <DialogTitle sx={dialogTitleSx}>攝影師詳情</DialogTitle>
            <DialogContent dividers sx={dialogContentSx}>
              {photographerDetailData ? (
                <Stack spacing={4}>
                  {/* 攝影師基本資料 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        基本資訊
                      </Typography>
                    </Box>
                    <Box sx={sectionGridSx}>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>攝影師ID</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.id}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>姓名</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.firstname}
                          {photographerDetailData.lastname}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>審核狀態</Typography>
                        <Box>
                          <Box sx={statusChipSx(photographerDetailData.status)}>
                            {statusMap[photographerDetailData.status] ||
                              photographerDetailData.status}
                          </Box>
                        </Box>
                      </Box>
                      {photographerDetailData.live_city && (
                        <Box sx={infoRowSx}>
                          <Typography sx={infoLabelSx}>居住城市</Typography>
                          <Typography sx={infoValueSx}>
                            {photographerDetailData.live_city}
                          </Typography>
                        </Box>
                      )}
                      {photographerDetailData.file_url && (
                        <Box sx={imageCardSx} mt={1}>
                          <Typography sx={infoLabelSx}>身分證照片</Typography>
                          <img
                            src={photographerDetailData.file_url}
                            alt="身份證"
                            style={previewImageStyle}
                          />
                        </Box>
                      )}
                    </Box>

                    <Divider sx={{ my: 2 }} />

                    <Box sx={sectionGridSx}>
                      <TextField
                        label="電話"
                        value={photographerVerifyForm.phone}
                        onChange={(e) =>
                          setPhotographerVerifyForm((prev) => ({
                            ...prev,
                            phone: e.target.value,
                          }))
                        }
                        fullWidth
                      />
                      <TextField
                        label="身分證字號"
                        value={photographerVerifyForm.id_card}
                        onChange={(e) =>
                          setPhotographerVerifyForm((prev) => ({
                            ...prev,
                            id_card: e.target.value,
                          }))
                        }
                        fullWidth
                      />
                      <TextField
                        label="生日"
                        type="date"
                        value={photographerVerifyForm.birthday}
                        onChange={(e) =>
                          setPhotographerVerifyForm((prev) => ({
                            ...prev,
                            birthday: e.target.value,
                          }))
                        }
                        InputLabelProps={{ shrink: true }}
                        helperText="格式：YYYY-MM-DD"
                        fullWidth
                      />
                      <Stack
                        direction={{ xs: "column", sm: "row" }}
                        justifyContent={{ xs: "stretch", sm: "flex-end" }}
                        alignItems="center"
                      >
                        <Button
                          variant="contained"
                          onClick={() =>
                            handleUpdateVerifyInfo(
                              photographerDetailData?.id,
                              photographerVerifyForm
                            )
                          }
                        >
                          儲存實名資料
                        </Button>
                      </Stack>
                    </Box>
                  </Box>

                  {/* 收款方式 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        收款方式
                      </Typography>
                    </Box>
                    <Stack spacing={1.5}>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>收款帳號</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.bank_account || "未提供"}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>帳戶名稱</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.bank_name || "未提供"}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>銀行名稱</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.bank || "未提供"}
                        </Typography>
                      </Box>
                      <Box sx={infoRowSx}>
                        <Typography sx={infoLabelSx}>分行名稱</Typography>
                        <Typography sx={infoValueSx}>
                          {photographerDetailData.bank_sub || "未提供"}
                        </Typography>
                      </Box>
                      {photographerDetailData.bank_file_url && (
                        <Box sx={imageCardSx} mt={1}>
                          <Typography sx={infoLabelSx}>銀行存摺照片</Typography>
                          <img
                            src={photographerDetailData.bank_file_url}
                            alt="存摺"
                            style={previewImageStyle}
                          />
                        </Box>
                      )}
                    </Stack>
                  </Box>

                  {/* 可拍攝地點 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        可拍攝地點
                      </Typography>
                    </Box>
                    <Stack spacing={2}>
                      {photographerDetailData.addr_responses?.length > 0 && (
                        <Box>
                          <Typography variant="subtitle2" color="text.secondary">
                            目前設定
                          </Typography>
                          <Stack spacing={1} sx={{ mt: 1 }}>
                            {photographerDetailData.addr_responses.map(
                              (addr, idx) => (
                                <Typography key={idx} sx={{ ml: 2 }}>
                                  {addr.addr} (lat: {addr.lat}, lng: {addr.lng})
                                </Typography>
                              )
                            )}
                          </Stack>
                        </Box>
                      )}

                      <Stack spacing={2}>
                        {photographerAddresses.map((item, idx) => (
                          <Box
                            key={`editable-addr-${idx}`}
                            sx={{
                              border: "1px solid #e0e0e0",
                              borderRadius: 2,
                              padding: 2,
                            }}
                          >
                            <Stack
                              direction="row"
                              justifyContent="space-between"
                              alignItems="center"
                              mb={1}
                            >
                              <Typography variant="subtitle2">
                                第 {idx + 1} 區
                              </Typography>
                              {photographerAddresses.length > 1 && (
                                <Button
                                  size="small"
                                  color="error"
                                  onClick={() => handleRemoveAddressRow(idx)}
                                >
                                移除
                                </Button>
                              )}
                            </Stack>
                            <Stack spacing={2}>
                              <TextField
                                label="地址"
                                value={item.addr}
                                onChange={(e) =>
                                  handleAddressFieldChange(
                                    idx,
                                    "addr",
                                    e.target.value
                                  )
                                }
                                fullWidth
                              />
                              <Stack
                                direction={{ xs: "column", sm: "row" }}
                                spacing={2}
                              >
                                <TextField
                                  label="東經(lat)"
                                  type="number"
                                  value={item.lat}
                                  onChange={(e) =>
                                    handleAddressFieldChange(
                                      idx,
                                      "lat",
                                      e.target.value
                                    )
                                  }
                                  inputProps={{ step: "0.000001" }}
                                  fullWidth
                                />
                                <TextField
                                  label="北緯 (lng)"
                                  type="number"
                                  value={item.lng}
                                  onChange={(e) =>
                                    handleAddressFieldChange(
                                      idx,
                                      "lng",
                                      e.target.value
                                    )
                                  }
                                  inputProps={{ step: "0.000001" }}
                                  fullWidth
                                />
                              </Stack>
                            </Stack>
                          </Box>
                        ))}
                      </Stack>

                      <Button variant="outlined" onClick={handleAddAddressRow}>
                        新增
                      </Button>
                    </Stack>
                  </Box>



                  {/* 標籤多選更新 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        標籤 (可多選更新)
                      </Typography>
                    </Box>

                    {/* 靜態標籤 */}
                    <Typography variant="subtitle1" gutterBottom>
                      📷 靜態標籤
                    </Typography>
                    <FormGroup
                      row
                      sx={{ flexWrap: "wrap", gap: 1.5 }} // 讓它自動換行 + 間距
                    >
                      {staticLabels.map((item) => (
                        <FormControlLabel
                          key={item.label_id}
                          control={
                            <Checkbox
                              checked={selectedLabelIds.includes(item.label_id)}
                              onChange={(e) =>
                                handleCheckboxChange(e, item.label_id)
                              }
                            />
                          }
                          label={item.label}
                          sx={{ mr: 1 }} // 可選：水平方向多一點距離
                        />
                      ))}
                    </FormGroup>

                    {/* 動態標籤 */}
                    <Typography variant="subtitle1" gutterBottom sx={{ mt: 2 }}>
                      🎥 動態標籤
                    </Typography>
                    <FormGroup row sx={{ flexWrap: "wrap", gap: 1.5 }}>
                      {dynamicLabels.map((item) => (
                        <FormControlLabel
                          key={item.label_id}
                          control={
                            <Checkbox
                              checked={selectedLabelIds.includes(item.label_id)}
                              onChange={(e) =>
                                handleCheckboxChange(e, item.label_id)
                              }
                              sx={{ mr: 1 }} // 可選：水平方向多一點距離
                            />
                          }
                          label={item.label}
                        />
                      ))}
                    </FormGroup>
                  </Box>

                  {/* 作品/相簿 */}
                  <Box sx={detailSectionSx}>
                    <Box sx={sectionHeaderSx}>
                      <Box sx={sectionAccentSx} />
                      <Typography variant="h6" sx={sectionTitleSx}>
                        作品/相簿 (可更新)
                      </Typography>
                    </Box>
                    <Stack spacing={2}>
                      <TextField
                        label="作品連結 (work_url)"
                        value={workUrl}
                        onChange={(e) => setWorkUrl(e.target.value)}
                        fullWidth
                      />
                      {workUrl && (
                        <img
                          src={workUrl}
                          alt="作品"
                          style={previewImageStyle}
                        />
                      )}
                      <TextField
                        label="相簿連結 (photo_url)"
                        value={photoUrl}
                        onChange={(e) => setPhotoUrl(e.target.value)}
                        fullWidth
                      />
                      {photoUrl && (
                        <img
                          src={photoUrl}
                          alt="相簿"
                          style={previewImageStyle}
                        />
                      )}
                    </Stack>
                  </Box>
                </Stack>
              ) : (
                <Typography>無資料</Typography>
              )}
            </DialogContent>

            <DialogActions sx={dialogActionsSx}>
              <Button onClick={handleClosePhotographerDetail} variant="outlined">
                取消
              </Button>
              <Button variant="contained" onClick={handleUpdatePhotographerAll}>
                確定修改
              </Button>
            </DialogActions>
          </Dialog>

          {/* Snackbar */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={3000}
            onClose={handleCloseSnackbar}
            anchorOrigin={{ vertical: "top", horizontal: "center" }}
          >
            <Alert
              severity={snackbarSeverity}
              onClose={handleCloseSnackbar}
              sx={{ width: "100%" }}
            >
              {snackbarMsg}
            </Alert>
          </Snackbar>
        </Paper>
      </Container>
    </>
  );
};

export default MemberManagement;
