import { useEffect, useMemo, useState } from "react";
import { format } from "date-fns";
import DatePicker from "react-datepicker";
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Container,
  FormControlLabel,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TextField,
  Typography,
} from "@mui/material";
import "react-datepicker/dist/react-datepicker.css";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";
import {
  fetchCardTransactions,
  fetchInvoiceRecords,
  reissuePurchaseInvoice,
} from "../../../api/Order";

const createDefaultCardFilters = () => ({
  purchaseId: "",
  merchantOrderNo: "",
  tradeNo: "",
  status: "",
  tradeStatus: "",
  paymentType: "CREDIT",
  includeFailed: false,
  startDate: null,
  endDate: null,
});

const createDefaultInvoiceFilters = () => ({
  purchaseId: "",
  paymentTransactionId: "",
  merchantOrderNo: "",
  status: "",
  triggerSource: "",
  startDate: null,
  endDate: null,
});

const CARD_SORTABLE_COLUMNS = [
  { key: "purchase_id", label: "Purchase ID" },
  { key: "merchant_order_no", label: "Merchant Order No" },
  { key: "trade_no", label: "Trade No" },
  { key: "status", label: "Status" },
  { key: "trade_status", label: "Trade Status" },
  { key: "payment_type", label: "Payment Type" },
  { key: "create_time", label: "Create Time" },
  { key: "amount", label: "Amount" },
];

const INVOICE_SORTABLE_COLUMNS = [
  { key: "purchase_id", label: "Purchase ID" },
  { key: "payment_transaction_id", label: "Payment Transaction ID" },
  { key: "merchant_order_no", label: "Merchant Order No" },
  { key: "status", label: "Status" },
  { key: "trigger_source", label: "Trigger Source" },
  { key: "create_time", label: "Create Time" },
  { key: "update_time", label: "Update Time" },
];

const formatBeginDate = (date) => (date ? format(date, "yyyy-MM-dd") : undefined);

const formatEndDate = (date) => {
  if (!date) return undefined;
  const nextDay = new Date(date.getTime() + 24 * 60 * 60 * 1000);
  return format(nextDay, "yyyy-MM-dd");
};

const parseListResponse = (responseData) => {
  const data = responseData || {};
  const records = Array.isArray(data.records)
    ? data.records
    : Array.isArray(data)
    ? data
    : [];
  const total = data?.page?.total_count ?? records.length;
  return { records, total };
};

const renderCell = (value) => {
  if (value === undefined || value === null || value === "") return "-";
  return String(value);
};

const PaymentRecordManagement = () => {
  const [cardFilters, setCardFilters] = useState(createDefaultCardFilters);
  const [appliedCardFilters, setAppliedCardFilters] = useState(createDefaultCardFilters);
  const [cardRows, setCardRows] = useState([]);
  const [cardPage, setCardPage] = useState(0);
  const [cardLimit, setCardLimit] = useState(10);
  const [cardTotalCount, setCardTotalCount] = useState(0);
  const [cardSortField, setCardSortField] = useState("purchase_id");
  const [cardSortOrder, setCardSortOrder] = useState("desc");
  const [cardLoading, setCardLoading] = useState(false);

  const [invoiceFilters, setInvoiceFilters] = useState(createDefaultInvoiceFilters);
  const [appliedInvoiceFilters, setAppliedInvoiceFilters] =
    useState(createDefaultInvoiceFilters);
  const [invoiceRows, setInvoiceRows] = useState([]);
  const [invoicePage, setInvoicePage] = useState(0);
  const [invoiceLimit, setInvoiceLimit] = useState(10);
  const [invoiceTotalCount, setInvoiceTotalCount] = useState(0);
  const [invoiceSortField, setInvoiceSortField] = useState("create_time");
  const [invoiceSortOrder, setInvoiceSortOrder] = useState("desc");
  const [invoiceLoading, setInvoiceLoading] = useState(false);

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("info");

  const showSnackbar = (message, severity = "info") => {
    setSnackbarMsg(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };

  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  const cardBeginDate = useMemo(
    () => formatBeginDate(appliedCardFilters.startDate),
    [appliedCardFilters.startDate]
  );
  const cardEndDate = useMemo(
    () => formatEndDate(appliedCardFilters.endDate),
    [appliedCardFilters.endDate]
  );

  const invoiceBeginDate = useMemo(
    () => formatBeginDate(appliedInvoiceFilters.startDate),
    [appliedInvoiceFilters.startDate]
  );
  const invoiceEndDate = useMemo(
    () => formatEndDate(appliedInvoiceFilters.endDate),
    [appliedInvoiceFilters.endDate]
  );

  const getCardRecords = async () => {
    setCardLoading(true);
    try {
      const res = await fetchCardTransactions({
        purchase_id: appliedCardFilters.purchaseId,
        merchant_order_no: appliedCardFilters.merchantOrderNo,
        trade_no: appliedCardFilters.tradeNo,
        status: appliedCardFilters.status,
        trade_status: appliedCardFilters.tradeStatus,
        payment_type: appliedCardFilters.paymentType || "CREDIT",
        begin_date: cardBeginDate,
        end_date: cardEndDate,
        include_failed: appliedCardFilters.includeFailed ? true : undefined,
        page: cardPage + 1,
        limit: cardLimit,
        sort: cardSortField,
        order: cardSortOrder,
      });

      if (!res?.success) {
        showSnackbar(res?.message || "\u67e5\u8a62\u4ed8\u6b3e\u7d00\u9304\u5931\u6557", "error");
        return;
      }

      const { records, total } = parseListResponse(res.data);
      setCardRows(records);
      setCardTotalCount(total);
    } catch (error) {
      console.error("getCardRecords error:", error);
      showSnackbar("\u67e5\u8a62\u4ed8\u6b3e\u7d00\u9304\u767c\u751f\u932f\u8aa4", "error");
    } finally {
      setCardLoading(false);
    }
  };

  const getInvoiceIssueRecords = async () => {
    setInvoiceLoading(true);
    try {
      const res = await fetchInvoiceRecords({
        purchase_id: appliedInvoiceFilters.purchaseId,
        payment_transaction_id: appliedInvoiceFilters.paymentTransactionId,
        merchant_order_no: appliedInvoiceFilters.merchantOrderNo,
        status: appliedInvoiceFilters.status,
        trigger_source: appliedInvoiceFilters.triggerSource,
        begin_date: invoiceBeginDate,
        end_date: invoiceEndDate,
        page: invoicePage + 1,
        limit: invoiceLimit,
        sort: invoiceSortField,
        order: invoiceSortOrder,
      });

      if (!res?.success) {
        showSnackbar(res?.message || "\u67e5\u8a62\u767c\u7968\u958b\u7acb\u7d00\u9304\u5931\u6557", "error");
        return;
      }

      const { records, total } = parseListResponse(res.data);
      setInvoiceRows(records);
      setInvoiceTotalCount(total);
    } catch (error) {
      console.error("getInvoiceIssueRecords error:", error);
      showSnackbar("\u67e5\u8a62\u767c\u7968\u958b\u7acb\u7d00\u9304\u767c\u751f\u932f\u8aa4", "error");
    } finally {
      setInvoiceLoading(false);
    }
  };

  useEffect(() => {
    getCardRecords();
  }, [
    cardPage,
    cardLimit,
    cardSortField,
    cardSortOrder,
    appliedCardFilters,
    cardBeginDate,
    cardEndDate,
  ]);

  useEffect(() => {
    getInvoiceIssueRecords();
  }, [
    invoicePage,
    invoiceLimit,
    invoiceSortField,
    invoiceSortOrder,
    appliedInvoiceFilters,
    invoiceBeginDate,
    invoiceEndDate,
  ]);

  const handleCardSearch = () => {
    setCardPage(0);
    setAppliedCardFilters({ ...cardFilters });
  };

  const handleCardReset = () => {
    const defaultFilters = createDefaultCardFilters();
    setCardFilters(defaultFilters);
    setAppliedCardFilters(defaultFilters);
    setCardSortField("purchase_id");
    setCardSortOrder("desc");
    setCardPage(0);
  };

  const handleInvoiceSearch = () => {
    setInvoicePage(0);
    setAppliedInvoiceFilters({ ...invoiceFilters });
  };

  const handleInvoiceReset = () => {
    const defaultFilters = createDefaultInvoiceFilters();
    setInvoiceFilters(defaultFilters);
    setAppliedInvoiceFilters(defaultFilters);
    setInvoiceSortField("create_time");
    setInvoiceSortOrder("desc");
    setInvoicePage(0);
  };

  const handleCardSort = (field) => {
    if (cardSortField === field) {
      setCardSortOrder(cardSortOrder === "asc" ? "desc" : "asc");
    } else {
      setCardSortField(field);
      setCardSortOrder("asc");
    }
  };

  const handleInvoiceSort = (field) => {
    if (invoiceSortField === field) {
      setInvoiceSortOrder(invoiceSortOrder === "asc" ? "desc" : "asc");
    } else {
      setInvoiceSortField(field);
      setInvoiceSortOrder("asc");
    }
  };

  const handleReissueInvoice = async (merchantOrderNo) => {
    if (!merchantOrderNo) {
      showSnackbar("\u672a\u627e\u5230 merchant_order_no", "warning");
      return;
    }
    if (
      !window.confirm(
        `\u78ba\u8a8d\u624b\u52d5\u88dc\u958b\u767c\u7968\uff1f\nmerchant_order_no: ${merchantOrderNo}`
      )
    ) {
      return;
    }

    try {
      const res = await reissuePurchaseInvoice(merchantOrderNo);
      if (!res?.success) {
        showSnackbar(res?.message || "\u624b\u52d5\u88dc\u958b\u5931\u6557", "error");
        return;
      }

      showSnackbar("\u624b\u52d5\u88dc\u958b\u5df2\u9001\u51fa", "success");
      getCardRecords();
      getInvoiceIssueRecords();
    } catch (error) {
      console.error("handleReissueInvoice error:", error);
      showSnackbar("\u624b\u52d5\u88dc\u958b\u767c\u751f\u932f\u8aa4", "error");
    }
  };

  return (
    <>
      <Header />
      <LeftBar />

      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            {"\u4ed8\u6b3e\u7d00\u9304"}
          </Typography>

          <Box mb={2}>
            <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap">
              <TextField
                size="small"
                label="purchase_id"
                value={cardFilters.purchaseId}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, purchaseId: e.target.value }))
                }
              />
              <TextField
                size="small"
                label="merchant_order_no"
                value={cardFilters.merchantOrderNo}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, merchantOrderNo: e.target.value }))
                }
              />
              <TextField
                size="small"
                label="trade_no"
                value={cardFilters.tradeNo}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, tradeNo: e.target.value }))
                }
              />
              <TextField
                size="small"
                label="status"
                value={cardFilters.status}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, status: e.target.value }))
                }
              />
              <TextField
                size="small"
                label="trade_status"
                value={cardFilters.tradeStatus}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, tradeStatus: e.target.value }))
                }
              />

              <Select
                size="small"
                value={cardFilters.paymentType}
                onChange={(e) =>
                  setCardFilters((prev) => ({ ...prev, paymentType: e.target.value }))
                }
              >
                <MenuItem value="CREDIT">CREDIT</MenuItem>
                <MenuItem value="LINE_PAY">LINE_PAY</MenuItem>
                <MenuItem value="ATM">ATM</MenuItem>
              </Select>

              <FormControlLabel
                control={
                  <Checkbox
                    checked={cardFilters.includeFailed}
                    onChange={(e) =>
                      setCardFilters((prev) => ({
                        ...prev,
                        includeFailed: e.target.checked,
                      }))
                    }
                  />
                }
                label="\u5305\u542b\u5931\u6557\u4ea4\u6613"
              />

              <DatePicker
                selectsRange
                startDate={cardFilters.startDate}
                endDate={cardFilters.endDate}
                onChange={(update) => {
                  const [start, end] = update;
                  setCardFilters((prev) => ({
                    ...prev,
                    startDate: start,
                    endDate: end,
                  }));
                }}
                isClearable
                placeholderText="\u4ea4\u6613\u65e5\u671f\u7bc4\u570d"
              />

              <Button variant="contained" onClick={handleCardSearch}>
                {"\u67e5\u8a62"}
              </Button>
              <Button variant="outlined" onClick={handleCardReset}>
                {"\u91cd\u8a2d"}
              </Button>
            </Stack>
          </Box>

          <Typography variant="body2" sx={{ color: "#6b7280", mb: 1 }}>
            {"\u624b\u52d5\u88dc\u958b\u53ea\u6703\u5728 prod profile \u751f\u6548\u3002"}
          </Typography>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  {CARD_SORTABLE_COLUMNS.map((column) => (
                    <TableCell
                      key={column.key}
                      onClick={() => handleCardSort(column.key)}
                      sx={{ cursor: "pointer", "&:hover": { backgroundColor: "#f5f5f5" } }}
                    >
                      {column.label}{" "}
                      {cardSortField === column.key ? (cardSortOrder === "asc" ? "\u2191" : "\u2193") : ""}
                    </TableCell>
                  ))}
                  <TableCell>{"\u52d5\u4f5c"}</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {cardRows.map((row, index) => (
                  <TableRow
                    key={`${row.purchase_id || "purchase"}-${row.merchant_order_no || "m"}-${index}`}
                  >
                    <TableCell>{renderCell(row.purchase_id)}</TableCell>
                    <TableCell>{renderCell(row.merchant_order_no)}</TableCell>
                    <TableCell>{renderCell(row.trade_no)}</TableCell>
                    <TableCell>{renderCell(row.status)}</TableCell>
                    <TableCell>{renderCell(row.trade_status)}</TableCell>
                    <TableCell>{renderCell(row.payment_type)}</TableCell>
                    <TableCell>{renderCell(row.create_time)}</TableCell>
                    <TableCell>{renderCell(row.amount ?? row.total_amount)}</TableCell>
                    <TableCell>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => handleReissueInvoice(row.merchant_order_no)}
                        disabled={!row.merchant_order_no}
                      >
                        {"\u624b\u52d5\u88dc\u958b"}
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
                {!cardLoading && cardRows.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9} align="center">
                      {"\u76ee\u524d\u6c92\u6709\u4ed8\u6b3e\u7d00\u9304"}
                    </TableCell>
                  </TableRow>
                )}
                {cardLoading && (
                  <TableRow>
                    <TableCell colSpan={9} align="center">
                      {"\u8f09\u5165\u4e2d..."}
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <TablePagination
            component="div"
            count={cardTotalCount}
            page={cardPage}
            onPageChange={(_, newPage) => setCardPage(newPage)}
            rowsPerPage={cardLimit}
            onRowsPerPageChange={(event) => {
              setCardLimit(parseInt(event.target.value, 10));
              setCardPage(0);
            }}
          />
        </Paper>

        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            {"\u767c\u7968\u958b\u7acb\u7d00\u9304"}
          </Typography>

          <Box mb={2}>
            <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap">
              <TextField
                size="small"
                label="purchase_id"
                value={invoiceFilters.purchaseId}
                onChange={(e) =>
                  setInvoiceFilters((prev) => ({ ...prev, purchaseId: e.target.value }))
                }
              />
              <TextField
                size="small"
                label="payment_transaction_id"
                value={invoiceFilters.paymentTransactionId}
                onChange={(e) =>
                  setInvoiceFilters((prev) => ({
                    ...prev,
                    paymentTransactionId: e.target.value,
                  }))
                }
              />
              <TextField
                size="small"
                label="merchant_order_no"
                value={invoiceFilters.merchantOrderNo}
                onChange={(e) =>
                  setInvoiceFilters((prev) => ({
                    ...prev,
                    merchantOrderNo: e.target.value,
                  }))
                }
              />

              <Select
                size="small"
                displayEmpty
                value={invoiceFilters.status}
                onChange={(e) =>
                  setInvoiceFilters((prev) => ({ ...prev, status: e.target.value }))
                }
              >
                <MenuItem value="">ALL STATUS</MenuItem>
                <MenuItem value="SUCCESS">SUCCESS</MenuItem>
                <MenuItem value="FAIL">FAIL</MenuItem>
              </Select>

              <Select
                size="small"
                displayEmpty
                value={invoiceFilters.triggerSource}
                onChange={(e) =>
                  setInvoiceFilters((prev) => ({
                    ...prev,
                    triggerSource: e.target.value,
                  }))
                }
              >
                <MenuItem value="">ALL SOURCE</MenuItem>
                <MenuItem value="AUTO">AUTO</MenuItem>
                <MenuItem value="MANUAL">MANUAL</MenuItem>
              </Select>

              <DatePicker
                selectsRange
                startDate={invoiceFilters.startDate}
                endDate={invoiceFilters.endDate}
                onChange={(update) => {
                  const [start, end] = update;
                  setInvoiceFilters((prev) => ({
                    ...prev,
                    startDate: start,
                    endDate: end,
                  }));
                }}
                isClearable
                placeholderText="\u958b\u7acb\u65e5\u671f\u7bc4\u570d"
              />

              <Button variant="contained" onClick={handleInvoiceSearch}>
                {"\u67e5\u8a62"}
              </Button>
              <Button variant="outlined" onClick={handleInvoiceReset}>
                {"\u91cd\u8a2d"}
              </Button>
            </Stack>
          </Box>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  {INVOICE_SORTABLE_COLUMNS.map((column) => (
                    <TableCell
                      key={column.key}
                      onClick={() => handleInvoiceSort(column.key)}
                      sx={{ cursor: "pointer", "&:hover": { backgroundColor: "#f5f5f5" } }}
                    >
                      {column.label}{" "}
                      {invoiceSortField === column.key
                        ? invoiceSortOrder === "asc"
                          ? "\u2191"
                          : "\u2193"
                        : ""}
                    </TableCell>
                  ))}
                  <TableCell>Message</TableCell>
                  <TableCell>{"\u52d5\u4f5c"}</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {invoiceRows.map((row, index) => (
                  <TableRow
                    key={`${row.id || "invoice"}-${row.merchant_order_no || "m"}-${index}`}
                  >
                    <TableCell>{renderCell(row.purchase_id)}</TableCell>
                    <TableCell>{renderCell(row.payment_transaction_id)}</TableCell>
                    <TableCell>{renderCell(row.merchant_order_no)}</TableCell>
                    <TableCell>{renderCell(row.status)}</TableCell>
                    <TableCell>{renderCell(row.trigger_source)}</TableCell>
                    <TableCell>{renderCell(row.create_time)}</TableCell>
                    <TableCell>{renderCell(row.update_time)}</TableCell>
                    <TableCell>{renderCell(row.message ?? row.error_message)}</TableCell>
                    <TableCell>
                      <Button
                        size="small"
                        variant="outlined"
                        onClick={() => handleReissueInvoice(row.merchant_order_no)}
                        disabled={!row.merchant_order_no}
                      >
                        {"\u624b\u52d5\u88dc\u958b"}
                      </Button>
                    </TableCell>
                  </TableRow>
                ))}
                {!invoiceLoading && invoiceRows.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9} align="center">
                      {"\u76ee\u524d\u6c92\u6709\u767c\u7968\u958b\u7acb\u7d00\u9304"}
                    </TableCell>
                  </TableRow>
                )}
                {invoiceLoading && (
                  <TableRow>
                    <TableCell colSpan={9} align="center">
                      {"\u8f09\u5165\u4e2d..."}
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <TablePagination
            component="div"
            count={invoiceTotalCount}
            page={invoicePage}
            onPageChange={(_, newPage) => setInvoicePage(newPage)}
            rowsPerPage={invoiceLimit}
            onRowsPerPageChange={(event) => {
              setInvoiceLimit(parseInt(event.target.value, 10));
              setInvoicePage(0);
            }}
          />
        </Paper>
      </Container>

      <Snackbar
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Alert severity={snackbarSeverity} onClose={handleCloseSnackbar} sx={{ width: "100%" }}>
          {snackbarMsg}
        </Alert>
      </Snackbar>
    </>
  );
};

export default PaymentRecordManagement;
