import { useEffect, useState } from "react";
import {
  createVideo,
  deleteVideo,
  fetchVerifyUrl,
  fetchVideoList,
  updateVerifyUrl,
  updateVideo,
} from "../../../../src/api/setting";
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

// MUI
import {
  Alert,
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Paper,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from "@mui/material";

const VideoManagement = () => {
  // 影片列表
  const [videoList, setVideoList] = useState([]);

  // 新增影片表單
  const [newUrl, setNewUrl] = useState("");
  const [newTag, setNewTag] = useState("");
  const [verifyUrl, setVerifyUrl] = useState("");

  // 編輯 Dialog
  const [openEditDialog, setOpenEditDialog] = useState(false);
  const [editData, setEditData] = useState(null); // { id, url, tag }

  // Snackbar
  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  // 載入影片列表
  useEffect(() => {
    getVideoData();
    getVerifyUrlData();
  }, []);

  const getVideoData = async () => {
    try {
      const res = await fetchVideoList();
      if (res?.success) {
        setVideoList(res.data || []);
      } else {
        showSnackbar("❌ 取得影片列表失敗", "error");
      }
    } catch (err) {
      console.error("fetchVideoList error", err);
      showSnackbar("❌ 取得影片列表發生錯誤", "error");
    }
  };

  const getVerifyUrlData = async () => {
    try {
      const res = await fetchVerifyUrl();
      if (res?.success) {
        setVerifyUrl(res.data || "");
      } else {
        showSnackbar("❌ 取得實名驗證網址失敗", "error");
      }
    } catch (err) {
      console.error("fetchVerifyUrl error", err);
      showSnackbar("❌ 取得實名驗證網址發生錯誤", "error");
    }
  };

  const handleUpdateVerifyUrl = async () => {
    if (!verifyUrl.trim()) {
      showSnackbar("請輸入實名驗證網址", "warning");
      return;
    }

    try {
      const res = await updateVerifyUrl({ url: verifyUrl.trim() });
      if (res?.success) {
        showSnackbar("✅ 實名驗證網址更新成功", "success");
        getVerifyUrlData();
      } else {
        showSnackbar("❌ 實名驗證網址更新失敗", "error");
      }
    } catch (err) {
      console.error("updateVerifyUrl error", err);
      showSnackbar("❌ 實名驗證網址更新發生錯誤", "error");
    }
  };

  // 新增影片
  const handleCreate = async () => {
    if (!newUrl.trim()) {
      showSnackbar("請輸入影片 URL", "warning");
      return;
    }
    if (!newTag.trim()) {
      showSnackbar("請輸入影片標籤", "warning");
      return;
    }

    try {
      const res = await createVideo({ url: newUrl, tag: newTag });
      if (res?.success) {
        showSnackbar("✅ 新增影片成功！", "success");
        setNewUrl("");
        setNewTag("");
        getVideoData();
      } else {
        showSnackbar("❌ 新增影片失敗", "error");
      }
    } catch (err) {
      console.error("createVideo error", err);
      showSnackbar("❌ 新增影片發生錯誤", "error");
    }
  };

  // 編輯
  const handleOpenEdit = (item) => {
    setEditData({ ...item });
    setOpenEditDialog(true);
  };
  const handleCloseEditDialog = () => {
    setOpenEditDialog(false);
    setEditData(null);
  };
  const handleUpdate = async () => {
    if (!editData) return;
    const { id, url, tag } = editData;

    if (!url.trim()) {
      showSnackbar("影片 URL 不可為空", "warning");
      return;
    }
    if (!tag.trim()) {
      showSnackbar("影片標籤不可為空", "warning");
      return;
    }

    try {
      const res = await updateVideo(id, { url, tag });
      if (res?.success) {
        showSnackbar("✅ 影片修改成功", "success");
        handleCloseEditDialog();
        getVideoData();
      } else {
        showSnackbar("❌ 影片修改失敗", "error");
      }
    } catch (err) {
      console.error("updateVideo error", err);
      showSnackbar("❌ 修改影片發生錯誤", "error");
    }
  };

  // 刪除
  const handleDelete = async (id) => {
    if (!window.confirm("確定要刪除這支影片嗎？")) return;

    try {
      const res = await deleteVideo(id);
      if (res?.success) {
        showSnackbar("✅ 刪除成功", "success");
        getVideoData();
      } else {
        showSnackbar("❌ 刪除失敗", "error");
      }
    } catch (err) {
      console.error("deleteVideo error", err);
      showSnackbar("❌ 刪除發生錯誤", "error");
    }
  };

  // Snackbar
  const showSnackbar = (msg, severity = "info") => {
    setSnackbarMessage(msg);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  return (
    <>
      <Header />
      <LeftBar />
      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 3, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 3, fontWeight: 600 }}>
            🎬 影片管理
          </Typography>

          <Paper sx={{ p: 3, mb: 3 }} elevation={2}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              🔐 實名驗證網址設定
            </Typography>
            <Stack spacing={2} direction={{ xs: "column", md: "row" }}>
              <TextField
                fullWidth
                label="實名驗證網址 (URL)"
                value={verifyUrl}
                onChange={(e) => setVerifyUrl(e.target.value)}
              />
              <Button variant="contained" onClick={handleUpdateVerifyUrl}>
                儲存
              </Button>
            </Stack>
          </Paper>

          {/* 新增影片 */}
          <Paper sx={{ p: 3, mb: 3 }} elevation={2}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              ➕ 新增影片
            </Typography>
            <Stack spacing={2} direction={{ xs: "column", md: "row" }}>
              <TextField
                fullWidth
                label="影片連結 (URL)"
                value={newUrl}
                onChange={(e) => setNewUrl(e.target.value)}
              />
              <TextField
                fullWidth
                label="影片標籤 (輸入中文)"
                value={newTag}
                onChange={(e) => setNewTag(e.target.value)}
              />
              <Button variant="contained" onClick={handleCreate}>
                新增
              </Button>
            </Stack>
          </Paper>

          {/* 影片列表 */}
          <Paper sx={{ p: 3 }} elevation={2}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              📋 影片列表
            </Typography>
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>ID</TableCell>
                    <TableCell>影片連結</TableCell>
                    <TableCell>標籤</TableCell>
                    <TableCell align="center">操作</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {videoList.length > 0 ? (
                    videoList.map((item) => (
                      <TableRow key={item.id}>
                        <TableCell>{item.id}</TableCell>
                        <TableCell sx={{ wordBreak: "break-word", maxWidth: 300 }}>
                          {item.url}
                        </TableCell>
                        <TableCell>{item.tag}</TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={1} justifyContent="center">
                            <Button
                              size="small"
                              variant="outlined"
                              onClick={() => handleOpenEdit(item)}
                            >
                              編輯
                            </Button>
                            <Button
                              size="small"
                              variant="contained"
                              color="error"
                              onClick={() => handleDelete(item.id)}
                            >
                              刪除
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={4} align="center">
                        目前沒有任何影片資料
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          {/* 編輯 Dialog */}
          <Dialog open={openEditDialog} onClose={handleCloseEditDialog} fullWidth>
            <DialogTitle>✏️ 編輯影片</DialogTitle>
            <DialogContent dividers>
              {editData && (
                <Stack spacing={2} mt={1}>
                  <TextField
                    fullWidth
                    label="影片連結 (URL)"
                    value={editData.url}
                    onChange={(e) =>
                      setEditData((prev) => ({ ...prev, url: e.target.value }))
                    }
                  />
                  <TextField
                    fullWidth
                    label="影片標籤 (輸入中文)"
                    value={editData.tag || ""}
                    onChange={(e) =>
                      setEditData((prev) => ({ ...prev, tag: e.target.value }))
                    }
                  />
                </Stack>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseEditDialog}>取消</Button>
              <Button variant="contained" onClick={handleUpdate}>
                確定修改
              </Button>
            </DialogActions>
          </Dialog>

          {/* Snackbar */}
          <Snackbar
            open={snackbarOpen}
            autoHideDuration={3000}
            onClose={handleCloseSnackbar}
            anchorOrigin={{ vertical: "top", horizontal: "center" }}
          >
            <Alert
              onClose={handleCloseSnackbar}
              severity={snackbarSeverity}
              sx={{ width: "100%" }}
            >
              {snackbarMessage}
            </Alert>
          </Snackbar>
        </Paper>
      </Container>
    </>
  );
};

export default VideoManagement;
