import { Dialog, DialogActions, DialogContent } from "@mui/material";
import { useState } from "react";

import { StyledFlexBox, StyledImage } from "../../../styles/Shared.styles";
import PwdDetail from "./PwdDetail";


const HeaderDetail = ({ open, setDetailOpen, detailId }) => {
  const handleClose = () => {
    setDetailOpen(false);
  };
  const [selected, setSelected] = useState("detail");
  const [pwdDetailOpen, setPwdDetailOpen] = useState(false);
  const logOut = () => {
    localStorage.clear();
    window.location = "/";
  }
  return (
    <Dialog
      open={open}
      onClose={handleClose}
      scroll="paper"
      sx={{
        '& .MuiDialog-container': {
          justifyContent: 'flex-end',
          alignItems: 'flex-start'
        }
      }}
      PaperProps={{ sx: { top: 40, left: 10, m: 2 } }}
      BackdropProps={{ style: { backgroundColor: "transparent" } }}
    >

      <DialogContent dividers={scroll === "paper"} >
        <StyledFlexBox
          onClick={() => { setPwdDetailOpen(true) }}
          style={{ cursor: "pointer" }}
        >
          重設密碼
        </StyledFlexBox>
        <StyledFlexBox
          pt={3}
          color="#FB4A4A "
          onClick={() => { logOut() }}
          style={{ cursor: "pointer" }}
        >
          登出
        </StyledFlexBox>
        <PwdDetail
          open={pwdDetailOpen}
          setDetailOpen={setPwdDetailOpen}
        />
      </DialogContent>
    </Dialog>
  );
};

export default HeaderDetail;
