import { useState } from "react";
import { StyledFlexBox } from "../../styles/Shared.styles";
import HeaderDetail from "./HeaderDetail";

const Header = () => {
  const [detailOpen, setDetailOpen] = useState(false);

  return (
    <StyledFlexBox
      bg="#fff"
      justifyContent="space-between"
      px={24}
      height={52}
      position="fixed"
      width="100%"
    >
      <HeaderDetail
        open={detailOpen}
        setDetailOpen={setDetailOpen}
      />
      <StyledFlexBox
        lineHeight="36px"
        fontSize={24}
        pt={2}
        color="#930000"
        fontWeight={600}
      >
        BigTime
      </StyledFlexBox>
      <StyledFlexBox alignItems="center"
        style={{ cursor: "pointer" }} onClick={() => { setDetailOpen(true) }}>
        <StyledFlexBox
          fontSize={12}
          color="#505050"
          fontWeight={500}
          mb="2px"
          fontFamily="Noto Sans TC"
        >
          Admin
        </StyledFlexBox>
      </StyledFlexBox>
    </StyledFlexBox>
  );
};

export default Header;
