// api/Video.js
import { service } from "."; // 根據自己實際 service 引入

/**
 * 取得影片列表 (GET /bo/index/video)
 */
export const fetchVideoList = (data) => {
  return new Promise((resolve, reject) => {
    let url = "/bo/index/video";

    // 如同 fetchNewsList, 你如果有需要傳 query 參數，也可以這樣寫:
    // let queryParams = [];
    // if (data.page) queryParams.push(`page=${data.page}`);
    // if (queryParams.length > 0) {
    //   url += "?" + queryParams.join("&");
    // }

    service({
      url: url,
      method: "GET",
      data,
    })
      .then(async (res) => await resolve(res.data))
      .catch((error) => reject(error));
  });
};

