/**
 * 修改影片 (PUT /bo/index/video/{id})
 */
export const updateVideo = (id, data) => {
  return new Promise((resolve, reject) => {
    service({
      url: `/bo/index/video/${id}`,
      method: "PUT",
      data,
    })
      .then(async (res) => await resolve(res.data))
      .catch((error) => reject(error));
  });
};

