import Switch from "@mui/material/Switch";
import { useEffect, useState } from "react";
import * as XLSX from "xlsx";
import {
  fetchDynamicReport,
  fetchFlatReport,
  fetchOrderList,
  forcePurchaseSuccess,
  updatePurchaseIsCharge,
} from "../../../../src/api/Order"; // 依實際路徑
import Header from "../../../components/AdminHeader";
import LeftBar from "../../../components/AdminLeftBar";

import {
  Alert,
  Box,
  Button,
  Container,
  MenuItem,
  Paper,
  Select,
  Snackbar,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from "@mui/material";
import { format } from "date-fns";

import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css"; // 要記得引入 CSS

const OrderManagement = () => {
  const [purchaseType, setPurchaseType] = useState("");
  const [payType, setPayType] = useState("");
  const [dateRange, setDateRange] = useState([new Date(), new Date()]);
  const [startDate, endDate] = dateRange;
  const [isChargeFilter, setIsChargeFilter] = useState("");

  const [page, setPage] = useState(0);
  const [limit, setLimit] = useState(10);
  const [totalCount, setTotalCount] = useState(0);
  const [orderList, setOrderList] = useState([]);

  const [sortField, setSortField] = useState("id");
  const [sortOrder, setSortOrder] = useState("desc");

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState("");
  const [snackbarSeverity, setSnackbarSeverity] = useState("success");

  const showSnackbar = (message, severity = "info") => {
    setSnackbarMsg(message);
    setSnackbarSeverity(severity);
    setSnackbarOpen(true);
  };
  const handleCloseSnackbar = () => {
    setSnackbarOpen(false);
  };

  const getOrders = async () => {
    try {
      const pageIndex = page + 1;
      const res = await fetchOrderList({
        purchaseType,
        payType,
        begin_date: startDate ? format(startDate, "yyyy-MM-dd") : undefined,
        end_date: endDate
          ? format(
              new Date(endDate.getTime() + 24 * 60 * 60 * 1000),
              "yyyy-MM-dd"
            )
          : undefined,
        is_charge:
          isChargeFilter !== "" ? isChargeFilter === "true" : undefined,
        page: pageIndex,
        limit,
        order: sortOrder,
        sort: sortField,
      });
      if (res?.success) {
        const records = res.data?.records || [];
        setOrderList(records);
        const pageObj = res.data?.page || {};
        setTotalCount(pageObj.total_count || 0);
      } else {
        showSnackbar("取得訂單失敗", "error");
      }
    } catch (error) {
      console.error("getOrders error:", error);
      showSnackbar("取得訂單發生錯誤", "error");
    }
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
  };

  const handleToggleIsCharge = async (purchaseId, newValue) => {
    try {
      const res = await updatePurchaseIsCharge(purchaseId, newValue);
      if (res?.success) {
        getOrders();
      } else {
        showSnackbar("更改失敗", "error");
      }
    } catch (error) {
      console.error("getOrders error:", error);
      showSnackbar("更改失敗", "error");
    }
  };

  const handleForceSuccess = async (purchaseId) => {
    if (!purchaseId) return;
    if (!window.confirm("確定要強制結單嗎？")) return;

    try {
      const res = await forcePurchaseSuccess(purchaseId);
      if (res?.success) {
        showSnackbar("✅ 已強制結單", "success");
        getOrders();
      } else {
        showSnackbar(res?.message || "❌ 強制結單失敗", "error");
      }
    } catch (error) {
      console.error("handleForceSuccess error:", error);
      showSnackbar("❌ 強制結單發生錯誤", "error");
    }
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  const handleChangeRowsPerPage = (event) => {
    setLimit(parseInt(event.target.value, 10));
    setPage(0);
  };

  useEffect(() => {
    getOrders();
  }, [page, limit, purchaseType, payType, sortField, sortOrder]);

  const handleSearch = () => {
    setPage(0);
    getOrders();
  };
  const getGenderFromId = (id) => {
    if (id == null) return "";
    const s = String(id).trim();
    if (s.length < 2) return "";
    const d = s[1]; // 第二個字
    if (d === "1") return "男";
    if (d === "2") return "女";
    return ""; // 其他值就留空（或你想回傳 "不明" 也可以）
  };

  const handleExportFlat = async () => {
    try {
      if (!startDate || !endDate)
        return showSnackbar("請先選擇日期區間", "warning");
      const begin_date = format(startDate, "yyyy-MM-dd");
      const end_dateStr = format(
        new Date(endDate.getTime() + 24 * 60 * 60 * 1000),
        "yyyy-MM-dd"
      );
      const res = await fetchFlatReport({
        begin_date: begin_date,
        end_date: end_dateStr,
      });
      if (!res?.success)
        return showSnackbar(res?.message || "匯出失敗", "error");

      const list = Array.isArray(res.data) ? res.data : [];
      if (list.length === 0) return showSnackbar("查無資料", "info");

      const headers = [
        "訂單編號",
        "項目",
        "類別",
        "風格",
        "訂單金額",
        "攝影師酬勞",
        "平台利潤",
        "是否加購基礎調色",
        "是否精修",
        "時數",
        "客年齡",
        "客性別",
        "縣市",
        "接單攝影師名稱",
        "用戶名稱",
      ];

      // 轉為 AOA（避免欄位名稱對不上）
      const dataRows = list.map((it) => [
        it.purchase_id ?? "",
        it.label ?? "",
        it.group ?? "",
        it.style ?? "",
        it.total_amount ?? 0,
        it.photographer_commission ?? 0,
        it.platform_commission ?? 0,
        it.is_basic_editing_and_color_adjustment ?? "",
        it.is_advanced_editing ?? "",
        it.hours ?? 0,
        it.age ?? "",
        getGenderFromId(it.id_card),
        it.country ?? "",
        it.photographer_name ?? "",
        it.user_name ?? "",
      ]);

      const title = `日期範圍：${begin_date} ~ ${end_dateStr}`;
      const ws = XLSX.utils.aoa_to_sheet([[title], [], headers, ...dataRows]);
      // 合併第一列
      ws["!merges"] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: headers.length - 1 } },
      ];

      // 欄寬估算
      ws["!cols"] = headers.map((h, idx) => {
        const maxLen = Math.max(
          h.length,
          ...dataRows.map((r) => String(r[idx] ?? "").length)
        );
        return { wch: Math.min(Math.max(maxLen + 2, 10), 40) };
      });

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "照片營業報表");
      XLSX.writeFile(wb, `照片營業報表_${begin_date}~${end_dateStr}.xlsx`);
      showSnackbar("照片營業報表已下載", "success");
    } catch (e) {
      console.error(e);
      showSnackbar(e.message || "匯出失敗", "error");
    }
  };
  const handleExportDynamic = async () => {
    try {
      if (!startDate || !endDate)
        return showSnackbar("請先選擇日期區間", "warning");
      const begin_date = format(startDate, "yyyy-MM-dd");
      const end_dateStr = format(
        new Date(endDate.getTime() + 24 * 60 * 60 * 1000),
        "yyyy-MM-dd"
      );

      const res = await fetchDynamicReport({
        begin_date: begin_date,
        end_date: end_dateStr,
      });
      if (!res?.success)
        return showSnackbar(res?.message || "匯出失敗", "error");

      const list = Array.isArray(res.data) ? res.data : [];
      if (list.length === 0) return showSnackbar("查無資料", "info");

      const headers = [
        "訂單編號",
        "項目",
        "類別",
        "風格",
        "訂單金額",
        "攝影師酬勞",
        "平台利潤",
        "是否加購額外服務",
        "時數",
        "客年齡",
        "客性別",
        "縣市",
        "接單攝影師名稱",
        "用戶名稱",
      ];

      const dataRows = list.map((it) => [
        it.purchase_id ?? "",
        it.label ?? "",
        it.group ?? "",
        it.style ?? "",
        it.total_amount ?? 0,
        it.photographer_commission ?? 0,
        it.platform_commission ?? 0,
        it.is_have_service ?? "",
        it.hours ?? 0,
        it.age ?? "",
        getGenderFromId(it.id_card),
        it.country ?? "",
        it.photographer_name ?? "",
        it.user_name ?? "",
      ]);

      const title = `日期範圍：${begin_date} ~ ${end_dateStr}`;
      const ws = XLSX.utils.aoa_to_sheet([[title], [], headers, ...dataRows]);
      ws["!merges"] = [
        { s: { r: 0, c: 0 }, e: { r: 0, c: headers.length - 1 } },
      ];

      ws["!cols"] = headers.map((h, idx) => {
        const maxLen = Math.max(
          h.length,
          ...dataRows.map((r) => String(r[idx] ?? "").length)
        );
        return { wch: Math.min(Math.max(maxLen + 2, 10), 40) };
      });

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "影片營業報表");
      XLSX.writeFile(wb, `影片營業報表_${begin_date}~${end_dateStr}.xlsx`);
      showSnackbar("影片營業報表已下載", "success");
    } catch (e) {
      console.error(e);
      showSnackbar(e.message || "匯出失敗", "error");
    }
  };

  return (
    <>
      <Header />
      <LeftBar />

      <Container maxWidth="lg" sx={{ pt: 10, pb: 4 }}>
        <Paper sx={{ p: 2, mb: 4 }}>
          <Typography variant="h4" sx={{ mb: 2, fontWeight: 600 }}>
            訂單管理
          </Typography>

          {/* 篩選條件 */}
          <Box mb={2}>
            <Stack
              direction="row"
              spacing={2}
              alignItems="center"
              flexWrap="wrap"
            >
              {/* purchaseType 下拉 */}
              <Select
                size="small"
                value={purchaseType}
                onChange={(e) => setPurchaseType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部狀態</MenuItem>
                <MenuItem value="WAIT">WAIT</MenuItem>
                <MenuItem value="ACCEPT">ACCEPT</MenuItem>
                <MenuItem value="DOING">DOING</MenuItem>
                <MenuItem value="SUCCESS">SUCCESS</MenuItem>
                <MenuItem value="CANCEL">CANCEL</MenuItem>
              </Select>

              {/* payType 下拉 */}
              <Select
                size="small"
                value={payType}
                onChange={(e) => setPayType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部支付</MenuItem>
                <MenuItem value="NO_PAY">NO_PAY</MenuItem>
                <MenuItem value="SUCCESS">SUCCESS</MenuItem>
                <MenuItem value="FAIL">FAIL</MenuItem>
                <MenuItem value="APPLY_REFUND">APPLY_REFUND</MenuItem>
                <MenuItem value="REFUND">REFUND</MenuItem>
              </Select>
              <Select
                size="small"
                value={isChargeFilter}
                onChange={(e) => setIsChargeFilter(e.target.value)}
                displayEmpty
              >
                <MenuItem value="">全部清帳狀態</MenuItem>
                <MenuItem value="true">已清帳</MenuItem>
                <MenuItem value="false">未清帳</MenuItem>
              </Select>

              <DatePicker
                selectsRange={true}
                startDate={startDate}
                endDate={endDate}
                onChange={(update) => {
                  setDateRange(update);
                }}
                isClearable={true}
              />
              <Button variant="contained" onClick={handleSearch}>
                查詢
              </Button>
              <Button variant="outlined" onClick={handleExportFlat}>
                匯出照片報表
              </Button>
              <Button variant="outlined" onClick={handleExportDynamic}>
                匯出影片報表
              </Button>
            </Stack>
          </Box>

          {/* 訂單列表 */}
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell
                    onClick={() => handleSort("id")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    訂單ID{" "}
                    {sortField === "id" && (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("create_time")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    建立時間{" "}
                    {sortField === "create_time" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("label")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    標籤{" "}
                    {sortField === "label" && (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("style")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    風格{" "}
                    {sortField === "style" && (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("user_name")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    下單用戶名稱{" "}
                    {sortField === "user_name" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("user_id")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    下單用戶ID{" "}
                    {sortField === "user_id" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("photographer_user_name")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    接單用戶名稱{" "}
                    {sortField === "photographer_user_name" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("photographer_id")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    接單用戶ID{" "}
                    {sortField === "photographer_id" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("photographer_commission")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    接單者酬勞{" "}
                    {sortField === "photographer_commission" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("purchase_type")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    訂單狀態{" "}
                    {sortField === "purchase_type" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("pay_type")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    付款狀態{" "}
                    {sortField === "pay_type" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("is_charge")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    是否清帳{" "}
                    {sortField === "is_charge" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell
                    onClick={() => handleSort("total_amount")}
                    sx={{
                      cursor: "pointer",
                      "&:hover": { backgroundColor: "#f5f5f5" },
                    }}
                  >
                    金額{" "}
                    {sortField === "total_amount" &&
                      (sortOrder === "asc" ? "↑" : "↓")}
                  </TableCell>
                  <TableCell align="center">操作</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {orderList.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell>{item.id}</TableCell>
                    <TableCell>{item.create_time}</TableCell>
                    <TableCell>{item.label}</TableCell>
                    <TableCell>{item.style}</TableCell>
                    <TableCell>{item.user_name}</TableCell>
                    <TableCell>{item.user_id}</TableCell>
                    <TableCell>{item.photographer_user_name}</TableCell>
                    <TableCell>{item.photographer_id}</TableCell>
                    <TableCell>{item.photographer_commission}</TableCell>
                    <TableCell>{item.purchase_type}</TableCell>
                    <TableCell>{item.pay_type}</TableCell>
                    <TableCell>
                      {item.purchase_type === "SUCCESS" ? (
                        <Switch
                          checked={item.is_charge}
                          onChange={(e) =>
                            handleToggleIsCharge(item.id, e.target.checked)
                          }
                          color="primary"
                        />
                      ) : (
                        "尚未完成"
                      )}
                    </TableCell>
                    <TableCell>{item.total_amount}</TableCell>
                    <TableCell align="center">
                      {item.purchase_type === "SUCCESS" ? (
                        "已結單"
                      ) : (
                        <Button
                          size="small"
                          variant="contained"
                          color="warning"
                          onClick={() =>
                            handleForceSuccess(item.purchase_id ?? item.id)
                          }
                        >
                          強制結單
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
                {orderList.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={14} align="center">
                      目前沒有訂單資料
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {/* 分頁器 */}
          <TablePagination
            component="div"
            count={totalCount}
            page={page}
            onPageChange={handleChangePage}
            rowsPerPage={limit}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </Paper>
      </Container>

      {/* Snackbar */}
      <Snackbar
        open={snackbarOpen}
        autoHideDuration={3000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Alert
          severity={snackbarSeverity}
          onClose={handleCloseSnackbar}
          sx={{ width: "100%" }}
        >
          {snackbarMsg}
        </Alert>
      </Snackbar>
    </>
  );
};

export default OrderManagement;
